/* 数据来源：doc/八卦.docx —— 六十四卦卦辞、爻辞、译文、解析 */
window.BAGUA_HEXAGRAMS = {"meta":{"title":"易 · 六十四卦","subtitle":"基于《周易》六十四卦整理","source":"八卦.docx","version":"1.0.0"},"trigrams":[{"sym":"☰","name":"乾","pinyin":"qián","image":"天","bits":[1,1,1],"virtue":"健，自强不息","meaning":"刚健、主动、光明、进取、天、力量、君子、奇数"},{"sym":"☷","name":"坤","pinyin":"kūn","image":"地","bits":[0,0,0],"virtue":"顺，厚德载物","meaning":"柔顺、包容、沉静、退让、地、承载、收敛、偶数"},{"sym":"☳","name":"震","pinyin":"zhèn","image":"雷","bits":[1,0,0],"virtue":"动，警醒奋起","meaning":"震动、奋发、长子、行动"},{"sym":"☶","name":"艮","pinyin":"gèn","image":"山","bits":[0,0,1],"virtue":"止，知止克制","meaning":"静止、阻隔、停止、少男、坚守"},{"sym":"☲","name":"离","pinyin":"lí","image":"火","bits":[1,0,1],"virtue":"明，依附、光明","meaning":"光明、附丽、文明、中女、明察"},{"sym":"☵","name":"坎","pinyin":"kǎn","image":"水","bits":[0,1,0],"virtue":"险，险中守正","meaning":"险陷、坎坷、中男、智慧、流动"},{"sym":"☱","name":"兑","pinyin":"duì","image":"泽","bits":[1,1,0],"virtue":"悦，和乐沟通","meaning":"喜悦、口舌、少女、沟通、和乐"},{"sym":"☴","name":"巽","pinyin":"xùn","image":"风","bits":[0,1,1],"virtue":"入，顺势谦逊","meaning":"顺入、谦逊、风行、长女、渗透"}],"hexagrams":[{"num":1,"name":"乾","pinyin":"qián","fullName":"乾为天","binary":[1,1,1,1,1,1],"upper":{"sym":"☰","name":"乾","image":"天","pinyin":"qián"},"lower":{"sym":"☰","name":"乾","image":"天","pinyin":"qián"},"guaci":{"text":"乾，元亨，利贞","trans":"乾，大通顺，利于坚守正道。","anal":"纯阳刚健，自强不息，守正方能长久。"},"lines":[{"label":"初九","text":"潜龙勿用","trans":"龙潜伏在深渊，不要有所作为。","anal":"时机未到，积蓄力量，隐忍待时。"},{"label":"九二","text":"见龙在田，利见大人","trans":"龙出现在田野，适合去拜见有德有才的长者。","anal":"能力初显，可以施展，结交良师。"},{"label":"九三","text":"君子终日乾乾，夕惕若厉，无咎","trans":"君子白天勤勉奋进，夜晚仍然警惕如临险境，没有过错。","anal":"小有成就，时刻自省，不能松懈。"},{"label":"九四","text":"或跃在渊，无咎","trans":"或者腾跃而上，或者退守深渊，进退由时，没有过错。","anal":"处在关键抉择点，可进可退，审慎选择。"},{"label":"九五","text":"飞龙在天，利见大人","trans":"龙高飞于天上，适合见到大德之人。","anal":"盛位，大展宏图，顺势而行。"},{"label":"上九","text":"亢龙有悔","trans":"龙飞到极高之处，会有悔恨。","anal":"物极必反，到达顶峰不可骄傲，知止。"}],"yong":null},{"num":2,"name":"坤","pinyin":"kūn","fullName":"坤为地","binary":[0,0,0,0,0,0],"upper":{"sym":"☷","name":"坤","image":"地","pinyin":"kūn"},"lower":{"sym":"☷","name":"坤","image":"地","pinyin":"kūn"},"guaci":{"text":"坤，元亨，利牝马之贞。君子有攸往，先迷后得主，利。西南得朋，东北丧朋。安贞吉","trans":"坤，大通顺，像母马一样柔顺守正就有利。君子出行，争先会迷失，跟随在后才有归宿；往西南能得到同伴，往东北失去同伴。安守正道吉祥。","anal":"纯阴，厚德载物，重在包容、顺势，不争先。"},"lines":[{"label":"初六","text":"履霜，坚冰至","trans":"踩到薄霜，就该预见坚冰将要到来。","anal":"见微知著，从小苗头预判后续发展。"},{"label":"六二","text":"直方大，不习无不利","trans":"正直、端方、广阔，不必刻意修习，也没有不利。","anal":"本性正直坦荡，自然顺遂。"},{"label":"六三","text":"含章可贞。或从王事，无成有终","trans":"内含文采美德，守正。辅佐事业，不居功，善守结局。","anal":"有才而不张扬，辅佐他人，不抢功劳。"},{"label":"六四","text":"括囊，无咎无誉","trans":"收紧口袋，缄默不言，没有过错，也没有赞誉。","anal":"时局不明，少说多做，收敛自保。"},{"label":"六五","text":"黄裳，元吉","trans":"身着黄色下裳，大吉。","anal":"居中守柔，谦卑内敛，居高位而不张扬。"},{"label":"上六","text":"龙战于野，其血玄黄","trans":"龙在原野交战，流出青黄混杂的血。","anal":"阴极盛而与阳相争，争斗两伤。"}],"yong":{"label":"用六","text":"利永贞","trans":"利于长久坚守柔顺正道。","anal":"坤卦总断，恒久守顺。"}},{"num":3,"name":"屯","pinyin":"zhūn","fullName":"水雷屯","binary":[1,0,0,0,1,0],"upper":{"sym":"☵","name":"坎","image":"水","pinyin":"kǎn"},"lower":{"sym":"☳","name":"震","image":"雷","pinyin":"zhèn"},"guaci":{"text":"屯，元亨，利贞。勿用有攸往，利建侯","trans":"屯，大通顺，利于守正。不要贸然前进，适合建立根基、开创事业。","anal":"初生萌芽，艰难而有生机，先固本。"},"lines":[{"label":"初九","text":"磐桓，利居贞，利建侯","trans":"徘徊不前，利于安居守正，利于建立根基。","anal":"初创艰难，不宜冒进，扎根。"},{"label":"六二","text":"屯如邅如，乘马班如。匪寇婚媾，女子贞不字，十年乃字","trans":"困顿徘徊，骑马之人盘旋。不是强盗，是来求婚；女子守正不急于出嫁，十年之后才成婚。","anal":"好事多磨，姻缘、事业都要等待时机。"},{"label":"六三","text":"即鹿无虞，惟入于林中，君子几，不如舍，往吝","trans":"追逐野鹿，没有向导，只会迷失林中；君子知机，不如放弃，强行前往会有遗憾。","anal":"条件不足，不要追逐目标，及时止损。"},{"label":"六四","text":"乘马班如，求婚媾，往吉，无不利","trans":"骑马盘旋，前去求亲，前往吉祥，没有不利。","anal":"主动寻求助力，寻求合作，可行。"},{"label":"九五","text":"屯其膏，小贞吉，大贞凶","trans":"积蓄恩泽。小事守正吉祥，大事守正而不施恩则凶险。","anal":"力量有限，恩惠要适度，不可囤积不施。"},{"label":"上六","text":"乘马班如，泣血涟如","trans":"骑马盘旋，血泪不断。","anal":"困到极点，所求难成，陷入悲困。"}],"yong":null},{"num":4,"name":"蒙","pinyin":"méng","fullName":"山水蒙","binary":[0,1,0,0,0,1],"upper":{"sym":"☶","name":"艮","image":"山","pinyin":"gèn"},"lower":{"sym":"☵","name":"坎","image":"水","pinyin":"kǎn"},"guaci":{"text":"蒙，亨。匪我求童蒙，童蒙求我。初筮告，再三渎，渎则不告。利贞","trans":"蒙，亨通。不是我去求蒙昧之人，是蒙昧者主动来求教。第一次诚心问就告知；反复轻慢地问，就不再回答。利于守正。","anal":"启蒙求学，贵在主动、恭敬。"},"lines":[{"label":"初六","text":"发蒙，利用刑人，用说桎梏，以往吝","trans":"启发蒙昧，用规矩约束；解除枷锁，但贸然前进仍有遗憾。","anal":"启蒙之初，要有规矩，不能放任。"},{"label":"九二","text":"包蒙吉，纳妇吉，子克家","trans":"包容蒙昧吉祥，迎娶妻子吉祥，孩子能够持家。","anal":"包容后进，宽厚教化，担当责任。"},{"label":"六三","text":"勿用取女，见金夫，不有躬，无攸利","trans":"不要娶这样的女子，见到有钱男子就失身，没有好处。","anal":"心志不坚定，不可托付，警惕立场摇摆。"},{"label":"六四","text":"困蒙，吝","trans":"困于蒙昧之中，有所遗憾。","anal":"远离良师益友，独自蒙昧，很难开悟。"},{"label":"六五","text":"童蒙，吉","trans":"像孩童一样虚心受教，吉祥。","anal":"虚心好学，放下成见，接受教导。"},{"label":"上九","text":"击蒙，不利为寇，利御寇","trans":"惩戒蒙昧，不适合主动施暴，适合抵御邪妄。","anal":"教化可以惩戒，但不能主动攻击。"}],"yong":null},{"num":5,"name":"需","pinyin":"xū","fullName":"水天需","binary":[1,1,1,0,1,0],"upper":{"sym":"☵","name":"坎","image":"水","pinyin":"kǎn"},"lower":{"sym":"☰","name":"乾","image":"天","pinyin":"qián"},"guaci":{"text":"需，有孚，光亨，贞吉。利涉大川","trans":"需，心怀诚信，光明亨通，守正则吉。可以渡过大河（渡过难关）。","anal":"等待积蓄，诚信自持，静待时机。"},"lines":[{"label":"初九","text":"需于郊，利用恒，无咎","trans":"在郊外等待，保持恒心，没有过错。","anal":"距离险难尚远，安心守常。"},{"label":"九二","text":"需于沙，小有言，终吉","trans":"在沙滩上等待，小有非议，最终吉祥。","anal":"渐渐靠近风险，有闲言，稳住则结局向好。"},{"label":"九三","text":"需于泥，致寇至","trans":"在泥滩等待，容易招引来祸患。","anal":"已经逼近险地，再不小心就招祸。"},{"label":"六四","text":"需于血，出自穴","trans":"在血泊险境中等待，从洞穴之中脱身。","anal":"身处险境，隐忍等待，寻找机会脱身。"},{"label":"九五","text":"需于酒食，贞吉","trans":"安享酒食从容等待，守正吉祥。","anal":"时机未至，从容调养，积蓄实力。"},{"label":"上六","text":"入于穴，有不速之客三人来，敬之终吉","trans":"回到居所，有三位不请自来的客人，恭敬对待，最终吉祥。","anal":"意外来客、变故，恭敬相待，化解矛盾。"}],"yong":null},{"num":6,"name":"讼","pinyin":"sòng","fullName":"天水讼","binary":[0,1,0,1,1,1],"upper":{"sym":"☰","name":"乾","image":"天","pinyin":"qián"},"lower":{"sym":"☵","name":"坎","image":"水","pinyin":"kǎn"},"guaci":{"text":"讼，有孚窒，惕，中吉，终凶。利见大人，不利涉大川","trans":"争讼，诚信被阻隔，心怀警惕，适度克制可得吉祥，一直争到底凶险。适合找有德长者裁决，不适合冒险远行。","anal":"争讼纠纷，尽量止争，久争两败俱伤。"},"lines":[{"label":"初六","text":"不永所事，小有言，终吉","trans":"不长久纠缠争端，小有口舌，最终吉祥。","anal":"争端浅，及时收手，不要纠缠。"},{"label":"九二","text":"不克讼，归而逋，其邑人三百户，无眚","trans":"官司败诉，赶紧逃回，他封邑三百户人家，没有灾祸。","anal":"争讼不胜，及时退让避祸，不硬扛。"},{"label":"六三","text":"食旧德，贞厉，终吉。或从王事，无成","trans":"安享旧日德业，守正虽有危，结局吉祥。辅佐事业，不居功。","anal":"不主动争竞，守本分，依托旧德自保。"},{"label":"九四","text":"不克讼，复即命，渝，安贞吉","trans":"争讼不能取胜，回归本分，改变争竞之心，安守正道吉祥。","anal":"认输悔改，放下争心，回归常理。"},{"label":"九五","text":"讼，元吉","trans":"审理争讼，大吉。","anal":"公正裁决是非，居中判案，公平。"},{"label":"上九","text":"或锡之鞶带，终朝三褫之","trans":"或许得到赏赐的华贵腰带，一天之内多次被剥夺。","anal":"靠争讼取胜得来的荣誉，终究保不住。"}],"yong":null},{"num":7,"name":"师","pinyin":"shī","fullName":"地水师","binary":[0,1,0,0,0,0],"upper":{"sym":"☷","name":"坤","image":"地","pinyin":"kūn"},"lower":{"sym":"☵","name":"坎","image":"水","pinyin":"kǎn"},"guaci":{"text":"师，贞，丈人吉，无咎","trans":"师，守正，有德老成的长者统帅则吉祥，没有过错。","anal":"军队、团队，统帅必须有德稳重，以正道行师。"},"lines":[{"label":"初六","text":"师出以律，否臧凶","trans":"军队出征必须有纪律；纪律败坏，凶险。","anal":"团队首要在于制度纪律。"},{"label":"九二","text":"在师中，吉，无咎，王三锡命","trans":"统帅在军中，吉祥无过，君王多次嘉奖授命。","anal":"主帅居中持正，深得信任。"},{"label":"六三","text":"师或舆尸，凶","trans":"军队可能载着尸身败退，凶险。","anal":"主帅无能，指挥失当，大败。"},{"label":"六四","text":"师左次，无咎","trans":"军队撤退驻扎，没有过错。","anal":"形势不利，懂得退守，不硬拼。"},{"label":"六五","text":"田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶","trans":"田中有猎物，适合仗义执言，无过。长子带兵可行，年幼后辈带兵会战败，守正也有凶险。","anal":"用人要得当，统帅要选合适之人。"},{"label":"上六","text":"大君有命，开国承家，小人勿用","trans":"天子颁下命令，分封诸侯、封赏大夫；小人不可任用。","anal":"战后封赏，慎用人，不能重用小人。"}],"yong":null},{"num":8,"name":"比","pinyin":"bǐ","fullName":"水地比","binary":[0,0,0,0,1,0],"upper":{"sym":"☵","name":"坎","image":"水","pinyin":"kǎn"},"lower":{"sym":"☷","name":"坤","image":"地","pinyin":"kūn"},"guaci":{"text":"比，吉。原筮，元永贞，无咎。不宁方来，后夫凶","trans":"比，吉祥。仔细考察，长久坚守正道，没有过失。不安的诸侯纷纷来依附，迟疑滞后的人会有凶险。","anal":"亲近团结，亲附正道，迟疑落后就被动。"},"lines":[{"label":"初六","text":"有孚比之，无咎。有孚盈缶，终来有他，吉","trans":"心怀诚信去亲近，没有过错。诚信满满，远方之人也会来归附，吉祥。","anal":"以诚待人，自然吸引同伴。"},{"label":"六二","text":"比之自内，贞吉","trans":"发自内心亲近正道，守正吉祥。","anal":"内心向善，主动亲附良善。"},{"label":"六三","text":"比之匪人","trans":"亲近的是不正之人。","anal":"结交坏人，依附错了对象，很危险。"},{"label":"六四","text":"外比之，贞吉","trans":"向外亲近贤良，守正吉祥。","anal":"向外看齐，追随正道贤者。"},{"label":"九五","text":"显比，王用三驱，失前禽。邑人不诫，吉","trans":"光明无私地亲近。君王打猎三面围猎，放走前面的野兽；百姓不戒备，吉祥。","anal":"包容宽厚，不强求别人归附，光明正大。"},{"label":"上六","text":"比之无首，凶","trans":"想要依附却没有领头方向，凶险。","anal":"没有目标、没有正道领袖，盲目依附。"}],"yong":null},{"num":9,"name":"小畜","pinyin":"xiǎo xù","fullName":"风天小畜","binary":[1,1,1,0,1,1],"upper":{"sym":"☴","name":"巽","image":"风","pinyin":"xùn"},"lower":{"sym":"☰","name":"乾","image":"天","pinyin":"qián"},"guaci":{"text":"小畜，亨。密云不雨，自我西郊","trans":"小畜，亨通。浓云密布却不下雨，云从西郊而来。","anal":"小有积蓄，力量不足，修养等待。"},"lines":[{"label":"初九","text":"复自道，何其咎，吉","trans":"回归正道，哪里会有过错，吉祥。","anal":"迷途知返，回到本来道路。"},{"label":"九二","text":"牵复，吉","trans":"与人一同回归正道，吉祥。","anal":"结伴向善，一同改过。"},{"label":"九三","text":"舆说辐，夫妻反目","trans":"车轮辐条脱落，夫妻反目不和。","anal":"积蓄不足，约束失衡，关系破裂。"},{"label":"六四","text":"有孚，血去惕出，无咎","trans":"心怀诚信，脱离忧患，解除警惕，没有过错。","anal":"以诚化解危机，放下惊惧。"},{"label":"九五","text":"有孚挛如，富以其邻","trans":"诚信相连，和邻居一同富足，共享所得。","anal":"富有之后，带动身边人。"},{"label":"上九","text":"既雨既处，尚德载。妇贞厉，月几望，君子征凶","trans":"雨已经降下，暂时安定，德行可以承载。妇人守正有危，月亮将近圆满，君子前进则凶。","anal":"积蓄已满，盛极将衰，不宜再进取。"}],"yong":null},{"num":10,"name":"履","pinyin":"lǚ","fullName":"天泽履","binary":[1,1,0,1,1,1],"upper":{"sym":"☰","name":"乾","image":"天","pinyin":"qián"},"lower":{"sym":"☱","name":"兑","image":"泽","pinyin":"duì"},"guaci":{"text":"履，履虎尾，不咥人，亨","trans":"履，踩在老虎尾巴上，老虎却不咬人，亨通。","anal":"身处险境，守礼谨慎，化险为夷。"},"lines":[{"label":"初九","text":"素履，往无咎","trans":"朴素本分，依常理而行，前行无过。","anal":"初心质朴，不投机取巧。"},{"label":"九二","text":"履道坦坦，幽人贞吉","trans":"行走在平坦大道，隐者守正吉祥。","anal":"守正道，内心安宁，不追逐浮华。"},{"label":"六三","text":"眇能视，跛能履，履虎尾，咥人，凶。武人为于大君","trans":"眼偏还自以为能看，脚跛还自以为能走；踩虎尾，被咬伤，凶险。武夫妄图做君主。","anal":"不自量力，能力不足却逞强，招致大祸。"},{"label":"九四","text":"履虎尾，愬愬，终吉","trans":"踩在虎尾，恐惧警惕，最终吉祥。","anal":"心存敬畏，谨慎小心，可脱险。"},{"label":"九五","text":"夬履，贞厉","trans":"果决独行，守正也有危险。","anal":"刚强决断，一意孤行，容易失度。"},{"label":"上九","text":"视履考祥，其旋元吉","trans":"回顾自己一路走来的行为，考察吉凶，回转自省，大吉。","anal":"复盘反省，总结得失，回头修正。"}],"yong":null},{"num":11,"name":"泰","pinyin":"tài","fullName":"地天泰","binary":[1,1,1,0,0,0],"upper":{"sym":"☷","name":"坤","image":"地","pinyin":"kūn"},"lower":{"sym":"☰","name":"乾","image":"天","pinyin":"qián"},"guaci":{"text":"泰，小往大来，吉亨","trans":"泰，小的向外散去，大的向内到来，吉祥亨通。","anal":"阴阳相交，上下相通，局势通达安泰。"},"lines":[{"label":"初九","text":"拔茅茹，以其汇，征吉","trans":"拔茅草，连带同类草根一起出来；前进吉祥。","anal":"志同道合，连带而起，顺势进取。"},{"label":"九二","text":"包荒，用冯河，不遐遗，朋亡，得尚于中行","trans":"包容广阔，敢于渡河冒险，不遗弃远方之人，不结党营私，守中道受人推崇。","anal":"胸怀宽广，大公无私，持守中道。"},{"label":"九三","text":"无平不陂，无往不复，艰贞无咎。勿恤其孚，于食有福","trans":"没有平地不倾斜，没有只去不回的。艰难守正无过，不必忧虑诚信，自有福分。","anal":"盛衰循环，平稳之中暗藏转折，艰难守正。"},{"label":"六四","text":"翩翩，不富以其邻，不戒以孚","trans":"轻盈往来，不独自占有财富，和邻居共享，不必戒备，彼此诚信。","anal":"上下相通，诚信相待，互通有无。"},{"label":"六五","text":"帝乙归妹，以祉元吉","trans":"帝乙嫁女，以此得福，大吉。","anal":"联姻、和合，以柔顺配合尊者，得福。"},{"label":"上六","text":"城复于隍，勿用师。自邑告命，贞吝","trans":"城墙崩塌在护城河里，不可兴师动众。从城邑下达政令，守正也有遗憾。","anal":"泰极转否，大势倾覆，不可强行征伐。"}],"yong":null},{"num":12,"name":"否","pinyin":"pǐ","fullName":"天地否","binary":[0,0,0,1,1,1],"upper":{"sym":"☰","name":"乾","image":"天","pinyin":"qián"},"lower":{"sym":"☷","name":"坤","image":"地","pinyin":"kūn"},"guaci":{"text":"否，否之匪人，不利君子贞，大往小来","trans":"否，闭塞不通，不是正道之人当道，不利于君子固守，大的好处流失，小的到来。","anal":"上下隔绝、闭塞对立，君子收敛自保。"},"lines":[{"label":"初六","text":"拔茅茹，以其汇，贞吉，亨","trans":"拔茅草连带同类，守正吉祥，亨通。","anal":"闭塞之初，同类相联，坚守正道。"},{"label":"六二","text":"包承，小人吉，大人否，亨","trans":"包容顺承，小人得吉；大德君子安守闭塞，最终亨通。","anal":"小人顺势迎合，君子不与同流。"},{"label":"六三","text":"包羞","trans":"包容羞耻之事。","anal":"身处污浊环境，忍辱藏羞，不得已。"},{"label":"九四","text":"有命，无咎，畴离祉","trans":"顺承天命，没有过错，同类一同得福。","anal":"闭塞之中，转机初现，同道受益。"},{"label":"九五","text":"休否，大人吉。其亡其亡，系于苞桑","trans":"停止闭塞，大德之人吉祥。时刻警惕将要灭亡，如同拴在柔弱桑枝上。","anal":"扭转闭塞，但常怀危惧，不能放松。"},{"label":"上九","text":"倾否，先否后喜","trans":"推翻闭塞的局面，先闭塞，后欢喜。","anal":"否极泰来，闭塞到尽头，局面翻转。"}],"yong":null},{"num":13,"name":"同人","pinyin":"tóng rén","fullName":"天火同人","binary":[1,0,1,1,1,1],"upper":{"sym":"☰","name":"乾","image":"天","pinyin":"qián"},"lower":{"sym":"☲","name":"离","image":"火","pinyin":"lí"},"guaci":{"text":"同人于野，亨。利涉大川，利君子贞","trans":"在广阔原野上和人同心，亨通。利于渡过险难，利于君子守正。","anal":"破除私心，广泛团结众人。"},"lines":[{"label":"初九","text":"同人于门，无咎","trans":"出门就与人同心，没有过错。","anal":"一开始就心胸开阔，广结善缘。"},{"label":"六二","text":"同人于宗，吝","trans":"只和宗族内部同心，格局狭小，有遗憾。","anal":"只搞小圈子，偏私狭隘。"},{"label":"九三","text":"伏戎于莽，升其高陵，三岁不兴","trans":"埋伏军队在草丛，登上高地观望，多年不能兴兵开战。","anal":"暗藏敌意，猜忌对峙，难以同心。"},{"label":"九四","text":"乘其墉，弗克攻，吉","trans":"登上城墙，却不发起进攻，吉祥。","anal":"虽有对抗之势，克制攻伐之心，止争为善。"},{"label":"九五","text":"同人，先号啕而后笑。大师克相遇","trans":"同心之人，先痛哭，后欢笑。大军战胜之后得以会合。","anal":"同心之路历经艰难，冲破阻隔之后相聚。"},{"label":"上九","text":"同人于郊，无悔","trans":"在郊外与人同心，没有悔恨。","anal":"远离闹市，不求功名，淡然相交。"}],"yong":null},{"num":14,"name":"大有","pinyin":"dà yǒu","fullName":"火天大有","binary":[1,1,1,1,0,1],"upper":{"sym":"☲","name":"离","image":"火","pinyin":"lí"},"lower":{"sym":"☰","name":"乾","image":"天","pinyin":"qián"},"guaci":{"text":"大有，元亨","trans":"大有，大通顺。","anal":"大有收获，拥有财富成就，光明守正，戒骄。"},"lines":[{"label":"初九","text":"无交害，匪咎，艰则无咎","trans":"没有交往带来的祸害，不是过错；常怀艰难之心，就无过错。","anal":"刚有收获，不攀附权贵，居安思危。"},{"label":"九二","text":"大车以载，有攸往，无咎","trans":"大车满载财物，有所前往，没有过错。","anal":"才德丰厚，可承载重任，稳步前行。"},{"label":"九三","text":"公用亨于天子，小人弗克","trans":"公侯向天子献贡，小人做不到。","anal":"富有之后，懂得奉献、尽本分，小人只会私藏。"},{"label":"九四","text":"匪其彭，无咎","trans":"不张扬炫耀丰盛，没有过错。","anal":"富有而不骄矜，收敛锋芒。"},{"label":"六五","text":"厥孚交如，威如，吉","trans":"诚信相交，庄重有威严，吉祥。","anal":"以诚信待人，又不失原则威严。"},{"label":"上九","text":"自天佑之，吉无不利","trans":"得到上天保佑，吉祥，无往不利。","anal":"顺天而行，积善有德，自然获得佑助。"}],"yong":null},{"num":15,"name":"谦","pinyin":"qiān","fullName":"地山谦","binary":[0,0,1,0,0,0],"upper":{"sym":"☷","name":"坤","image":"地","pinyin":"kūn"},"lower":{"sym":"☶","name":"艮","image":"山","pinyin":"gèn"},"guaci":{"text":"谦，亨。君子有终","trans":"谦，亨通。君子能够保持谦逊，善始善终。","anal":"六十四卦唯一全卦皆吉，谦受益。"},"lines":[{"label":"初六","text":"谦谦君子，用涉大川，吉","trans":"谦逊又谦逊的君子，可以渡过大河，吉祥。","anal":"谦卑自守，处处谨慎，可渡险难。"},{"label":"六二","text":"鸣谦，贞吉","trans":"名声在外而依旧谦逊，守正吉祥。","anal":"有才有名，仍然谦和。"},{"label":"九三","text":"劳谦，君子有终，吉","trans":"劳苦有功而谦逊，君子善始善终，吉祥。","anal":"付出功劳，不自居，最可贵。"},{"label":"六四","text":"无不利，㧑谦","trans":"无往不利，发挥谦逊之道。","anal":"无论什么处境，都保持谦抑。"},{"label":"六五","text":"不富以其邻，利用侵伐，无不利","trans":"不独自富足，和邻居共享；可以讨伐不义，无不利。","anal":"谦和不等于软弱，对恶可以征伐。"},{"label":"上六","text":"鸣谦，利用行师，征邑国","trans":"名声彰显而谦逊，适合出兵，征讨自己封邑内的不义。","anal":"德望足够，可兴正义之师。"}],"yong":null},{"num":16,"name":"豫","pinyin":"yù","fullName":"雷地豫","binary":[0,0,0,1,0,0],"upper":{"sym":"☳","name":"震","image":"雷","pinyin":"zhèn"},"lower":{"sym":"☷","name":"坤","image":"地","pinyin":"kūn"},"guaci":{"text":"豫，利建侯，行师","trans":"豫，利于分封诸侯、兴师出征。","anal":"人心安乐和顺，适合动员、谋划大事，戒沉溺享乐。"},"lines":[{"label":"初六","text":"鸣豫，凶","trans":"自鸣得意、沉溺安乐，凶险。","anal":"小有安乐就骄傲自满，坏事。"},{"label":"六二","text":"介于石，不终日，贞吉","trans":"操守坚如磐石，洞察祸福，不等一天过完就醒悟，守正吉祥。","anal":"清醒自持，安乐之中知警惕。"},{"label":"六三","text":"盱豫，悔。迟有悔","trans":"仰望讨好、贪图逸乐，会悔恨；迟疑不改，更有悔恨。","anal":"依附他人、贪图安逸，迟早后悔。"},{"label":"九四","text":"由豫，大有得。勿疑，朋盍簪","trans":"安乐由他而来，大有收获。不必怀疑，同道之人聚合，像发簪聚拢头发。","anal":"带动众人安乐，诚信凝聚人心。"},{"label":"六五","text":"贞疾，恒不死","trans":"守正防备疾患，长久不会败亡。","anal":"安乐之中暗藏隐患，持续防备，可长久维持。"},{"label":"上六","text":"冥豫，成有渝，无咎","trans":"昏昧沉迷享乐；如果及时改变，没有过错。","anal":"沉溺到极点，只要幡然改过，尚可无过。"}],"yong":null},{"num":17,"name":"随","pinyin":"suí","fullName":"泽雷随","binary":[1,0,0,1,1,0],"upper":{"sym":"☱","name":"兑","image":"泽","pinyin":"duì"},"lower":{"sym":"☳","name":"震","image":"雷","pinyin":"zhèn"},"guaci":{"text":"随，元亨，利贞，无咎","trans":"随，大通顺，利于守正，没有过错。","anal":"追随正道良善，顺势而为，不是盲从跟风。"},"lines":[{"label":"初九","text":"官有渝，贞吉。出门交有功","trans":"职责有变动，守正吉祥；出门交往，有所成就。","anal":"懂得变通，追随正道，广泛交友。"},{"label":"六二","text":"系小子，失丈夫","trans":"依附年幼小子，失去刚正长者。","anal":"选错追随对象，因小失大。"},{"label":"六三","text":"系丈夫，失小子。随有求得，利居贞","trans":"依附刚正长者，舍弃小子。追随而有所求可以得到，安居守正有利。","anal":"追随贤能大德，取舍得当。"},{"label":"九四","text":"随有获，贞凶。有孚在道，以明，何咎","trans":"追随而有所收获，守正也有凶险；心怀诚信守道，光明磊落，又有什么过错。","anal":"追随得利容易招疑，以诚明志。"},{"label":"九五","text":"孚于嘉，吉","trans":"诚信对待良善贤才，吉祥。","anal":"追随、信任美好正道之人。"},{"label":"上六","text":"拘系之，乃从维之。王用亨于西山","trans":"捆绑拘系，再牢牢维系。君王在西山祭祀。","anal":"诚心归附，紧紧相守，不再背离。"}],"yong":null},{"num":18,"name":"蛊","pinyin":"gǔ","fullName":"山风蛊","binary":[0,1,1,0,0,1],"upper":{"sym":"☶","name":"艮","image":"山","pinyin":"gèn"},"lower":{"sym":"☴","name":"巽","image":"风","pinyin":"xùn"},"guaci":{"text":"蛊，元亨，利涉大川。先甲三日，后甲三日","trans":"蛊，大通顺，利于渡过险难。在事情开端之前深思，在开端之后审慎调整。","anal":"积弊败坏，需要革新整顿，除旧布新。"},"lines":[{"label":"初六","text":"干父之蛊，有子，考无咎，厉终吉","trans":"匡正父辈留下的弊乱，有这样的儿子，父亲免于过错；虽有危险，最终吉祥。","anal":"后辈修正前人遗留弊病。"},{"label":"九二","text":"干母之蛊，不可贞","trans":"匡正母亲留下的弊乱，不可强硬固执。","anal":"对长辈的过失，委婉调和，不宜硬刚。"},{"label":"九三","text":"干父之蛊，小有悔，无大咎","trans":"匡正父辈弊乱，小有悔恨，没有大过错。","anal":"纠正弊病，手段偏刚，小有波折，但方向没错。"},{"label":"六四","text":"裕父之蛊，往见吝","trans":"宽容纵容父辈的弊乱，继续下去会有遗憾。","anal":"包庇积弊，不整治，后患显现。"},{"label":"六五","text":"干父之蛊，用誉","trans":"匡正父辈弊乱，获得赞誉。","anal":"中庸得当，妥善整改，受人称赞。"},{"label":"上九","text":"不事王侯，高尚其事","trans":"不侍奉王侯，坚守高洁志向。","anal":"弊乱世道，不愿同流，超然守志。"}],"yong":null},{"num":19,"name":"临","pinyin":"lín","fullName":"地泽临","binary":[1,1,0,0,0,0],"upper":{"sym":"☷","name":"坤","image":"地","pinyin":"kūn"},"lower":{"sym":"☱","name":"兑","image":"泽","pinyin":"duì"},"guaci":{"text":"临，元亨，利贞。至于八月有凶","trans":"临，大通顺，利于守正。到了八月阴盛之时会有凶险。","anal":"莅临治理，当下向好，盛极必衰，提前防备。"},"lines":[{"label":"初九","text":"咸临，贞吉","trans":"感应亲近，以德临民，守正吉祥。","anal":"用心感召，以德治理。"},{"label":"九二","text":"咸临，吉无不利","trans":"感应亲近，吉祥，无往不利。","anal":"刚健配合，感召治理，形势向好。"},{"label":"六三","text":"甘临，无攸利。既忧之，无咎","trans":"靠甜言巧辩来治理，没有好处；如果为此忧虑悔改，就无过错。","anal":"讨好式管理不可长久，醒悟则可补救。"},{"label":"六四","text":"至临，无咎","trans":"亲自莅临，贴近治理，没有过错。","anal":"亲临一线，体察实情。"},{"label":"六五","text":"知临，大君之宜，吉","trans":"以智慧治理，适合君主，吉祥。","anal":"知人善任，用智慧用人，不事事亲力亲为。"},{"label":"上六","text":"敦临，吉，无咎","trans":"敦厚诚恳地治理，吉祥，没有过错。","anal":"宽厚仁厚，以德化人。"}],"yong":null},{"num":20,"name":"观","pinyin":"guān","fullName":"风地观","binary":[0,0,0,0,1,1],"upper":{"sym":"☴","name":"巽","image":"风","pinyin":"xùn"},"lower":{"sym":"☷","name":"坤","image":"地","pinyin":"kūn"},"guaci":{"text":"观，盥而不荐，有孚颙若","trans":"观，洗净手还未献祭，心怀诚敬，庄重肃穆。","anal":"观察、自省、瞻仰，心怀敬畏，审慎看待事物。"},"lines":[{"label":"初六","text":"童观，小人无咎，君子吝","trans":"像孩童一样浅显观察，普通人无过，君子则有遗憾。","anal":"见识浅薄，看得太浅，君子不能停于此。"},{"label":"六二","text":"窥观，利女贞","trans":"从门缝里面偷看，适合女子守正。","anal":"视野狭隘，局限一隅，格局不大。"},{"label":"六三","text":"观我生，进退","trans":"观察自己的言行，审时进退。","anal":"向内自省，根据自身情况决定进退。"},{"label":"六四","text":"观国之光，利用宾于王","trans":"观察国家的光辉盛景，适合作为宾客朝见君王。","anal":"观察世道，见贤德君主，依附正道。"},{"label":"九五","text":"观我生，君子无咎","trans":"观察自己的治下民生，君子没有过错。","anal":"上位者自省，观察自己治理的得失。"},{"label":"上九","text":"观其生，君子无咎","trans":"观察天下众人的民生，君子没有过错。","anal":"跳出自身，广泛观察天下，自省修德。"}],"yong":null},{"num":21,"name":"噬嗑","pinyin":"shì hé","fullName":"火雷噬嗑","binary":[1,0,0,1,0,1],"upper":{"sym":"☲","name":"离","image":"火","pinyin":"lí"},"lower":{"sym":"☳","name":"震","image":"雷","pinyin":"zhèn"},"guaci":{"text":"噬嗑，亨。利用狱","trans":"噬嗑，亨通。适合审理刑狱、断决纠纷。","anal":"噬嗑是咬合、破除阻隔。中间有障碍，需要明断是非，清除隔阂。"},"lines":[{"label":"初九","text":"屦校灭趾，无咎","trans":"脚上戴上刑具，遮住脚趾，没有大过错。","anal":"小过即受惩戒，及时约束，防止继续犯错。"},{"label":"六二","text":"噬肤灭鼻，无咎","trans":"咬柔软的肉，连鼻子都埋进去，没有过错。","anal":"处置轻罪，顺势决断，手段直接。"},{"label":"六三","text":"噬腊肉，遇毒，小吝，无咎","trans":"啃腊肉，遇到毒质，小有麻烦，没有大过。","anal":"处理棘手旧案，会遇到麻烦，但本心公正，无大咎。"},{"label":"九四","text":"噬干胏，得金矢，利艰贞，吉","trans":"啃带骨头的干肉，得到金属箭头，在艰难中守正有利，吉祥。","anal":"案情复杂，坚持刚正，坚守正道方能突破。"},{"label":"六五","text":"噬干肉，得黄金，贞厉，无咎","trans":"啃干肉，得到黄金，守正虽有危险，没有过错。","anal":"居中断案，秉持中道，常怀警惕，可无过失。"},{"label":"上九","text":"何校灭耳，凶","trans":"肩上扛着重刑具，遮住耳朵，凶险。","anal":"屡教不改，听不进劝诫，最终招致重罚。"}],"yong":null},{"num":22,"name":"贲","pinyin":"bì","fullName":"山火贲","binary":[1,0,1,0,0,1],"upper":{"sym":"☶","name":"艮","image":"山","pinyin":"gèn"},"lower":{"sym":"☲","name":"离","image":"火","pinyin":"lí"},"guaci":{"text":"贲，亨。小利有攸往","trans":"贲，亨通。小事上适合有所行动。","anal":"贲为文饰、礼仪文采。外在修饰可以美化，但文不能盖过本质，重质轻文。"},"lines":[{"label":"初九","text":"贲其趾，舍车而徒","trans":"修饰自己的脚，舍弃车子步行。","anal":"修饰从根基做起，不慕浮华，守本分。"},{"label":"六二","text":"贲其须","trans":"修饰胡须。","anal":"依附主体而修饰，文饰服务于本质。"},{"label":"九三","text":"贲如濡如，永贞吉","trans":"文采润泽光鲜，长久守正吉祥。","anal":"文质搭配得当，但是不可沉溺纹饰。"},{"label":"六四","text":"贲如皤如，白马翰如，匪寇，婚媾","trans":"文饰褪去，素白质朴，白马飞驰，不是强盗，是来求亲的。","anal":"褪去浮华，回归质朴，真诚相交。"},{"label":"六五","text":"贲于丘园，束帛戋戋，吝，终吉","trans":"在山野园圃修饰，微薄的丝帛礼品，看似俭薄有遗憾，最终吉祥。","anal":"质朴简约，不求奢华，真情可贵。"},{"label":"上九","text":"白贲，无咎","trans":"素白无华的文饰，没有过错。","anal":"返璞归真，最高的文采就是朴素。"}],"yong":null},{"num":23,"name":"剥","pinyin":"bō","fullName":"山地剥","binary":[0,0,0,0,0,1],"upper":{"sym":"☶","name":"艮","image":"山","pinyin":"gèn"},"lower":{"sym":"☷","name":"坤","image":"地","pinyin":"kūn"},"guaci":{"text":"剥，不利有攸往","trans":"剥，不利于有所前往、进取。","anal":"剥是剥落、侵蚀。阳气不断被阴消，大势衰败，不宜进取，守静自保。"},"lines":[{"label":"初六","text":"剥床以足，蔑，贞凶","trans":"剥蚀床的床脚，消蚀根基，守正也有凶险。","anal":"祸患从底层根基开始腐蚀，要警惕微小隐患。"},{"label":"六二","text":"剥床以辨，蔑，贞凶","trans":"剥蚀床的床板，继续消蚀，守正也凶险。","anal":"危害向上蔓延，根基已经受损。"},{"label":"六三","text":"剥之，无咎","trans":"虽处在剥落之势，却可以无咎。","anal":"身处浊世，独守正道，不和小人同流。"},{"label":"六四","text":"剥床以肤，凶","trans":"剥蚀到床面，贴近人身，凶险。","anal":"祸患已经逼近自身，危险迫在眉睫。"},{"label":"六五","text":"贯鱼，以宫人宠，无不利","trans":"像一串游鱼有序排列，像宫人一样依次受宠，没有不利。","anal":"顺势引导，有序管束，不强行对抗。"},{"label":"上九","text":"硕果不食，君子得舆，小人剥庐","trans":"硕大的果实不被吃掉，君子得到大车承载，小人会拆毁屋舍。","anal":"衰败之时，留存正道根基；君子守正可担重任，小人会彻底毁坏根本。"}],"yong":null},{"num":24,"name":"复","pinyin":"fù","fullName":"地雷复","binary":[1,0,0,0,0,0],"upper":{"sym":"☷","name":"坤","image":"地","pinyin":"kūn"},"lower":{"sym":"☳","name":"震","image":"雷","pinyin":"zhèn"},"guaci":{"text":"复，亨。出入无疾，朋来无咎。反复其道，七日来复，利有攸往","trans":"复，亨通。出入没有疾患，志同道合者前来，没有过失。循环往复，七天回归正道，利于前行。","anal":"复是回归、复苏。衰败之后阳气回归，知错能改、回归本心，就是复兴。"},"lines":[{"label":"初九","text":"不远复，无祗悔，元吉","trans":"走不远就回头回归正道，没有大悔恨，大吉。","anal":"刚犯错就及时反省改正，止损最快。"},{"label":"六二","text":"休复，吉","trans":"美好的回归，吉祥。","anal":"主动向善，欣然回归正道。"},{"label":"六三","text":"频复，厉，无咎","trans":"多次反复摇摆，有危险，但没有大过错。","anal":"反复犯错又反复悔改，虽然艰难，但肯回头就不会覆灭。"},{"label":"六四","text":"中行独复","trans":"行在中道，独自回归正道。","anal":"众人迷失，唯独自己坚守本心回归。"},{"label":"六五","text":"敦复，无悔","trans":"敦厚诚心地回归正道，没有悔恨。","anal":"本性忠厚，踏实守道，不会后悔。"},{"label":"上六","text":"迷复，凶，有灾眚。用行师，终有大败，以其国君凶，至于十年不克征","trans":"迷失而不知回头，凶险，自带灾祸。如果兴兵，最终大败，君主也有凶险，十年不能再起征战。","anal":"执迷不悟，不肯悔改，祸患深重。"}],"yong":null},{"num":25,"name":"无妄","pinyin":"wú wàng","fullName":"天雷无妄","binary":[1,0,0,1,1,1],"upper":{"sym":"☰","name":"乾","image":"天","pinyin":"qián"},"lower":{"sym":"☳","name":"震","image":"雷","pinyin":"zhèn"},"guaci":{"text":"无妄，元亨，利贞。其匪正有眚，不利有攸往","trans":"无妄，大通顺，利于守正。不守正道就会有灾祸，不适合贸然行动。","anal":"无妄是不妄为、真诚。不胡思乱想、不投机妄想，老老实实依正道行事。"},"lines":[{"label":"初九","text":"无妄，往吉","trans":"心存真诚不妄为，前行吉祥。","anal":"初心纯正，顺势而行，没有虚妄。"},{"label":"六二","text":"不耕获，不菑畲，则利有攸往","trans":"不耕种就想着收获，不开荒就想要熟田，这样不可；守无妄之道，才利于前行。","anal":"不抱不劳而获的妄想，耕耘才有收获。"},{"label":"六三","text":"无妄之灾，或系之牛，行人之得，邑人之灾","trans":"意想不到的灾祸。有人拴着牛，路人顺手牵走，村里无辜之人蒙受嫌疑受灾。","anal":"自身无错，也可能遭遇意外牵连之灾，坦然面对。"},{"label":"九四","text":"可贞，无咎","trans":"可以坚守正道，没有过错。","anal":"守住本分，不妄求，安稳自持。"},{"label":"九五","text":"无妄之疾，勿药有喜","trans":"莫名的小病，不必强行用药调养，自行痊愈可喜。","anal":"有些意外波折，不必刻意强行干预，静待自愈。"},{"label":"上九","text":"无妄，行有眚，无攸利","trans":"虽本心无妄，但是贸然行动仍会有灾祸，没有好处。","anal":"时机不对，即使心意纯正，也不宜行动。"}],"yong":null},{"num":26,"name":"大畜","pinyin":"dà xù","fullName":"山天大畜","binary":[1,1,1,0,0,1],"upper":{"sym":"☶","name":"艮","image":"山","pinyin":"gèn"},"lower":{"sym":"☰","name":"乾","image":"天","pinyin":"qián"},"guaci":{"text":"大畜，利贞。不家食，吉。利涉大川","trans":"大畜，利于守正。贤才不只是在家吃俸禄，出来建功，吉祥，利于渡过险难。","anal":"大畜是大量积蓄，学识、德行、才能的积累。厚积之后，可以担当大任。"},"lines":[{"label":"初九","text":"有厉，利已","trans":"有危险，适合停止不动。","anal":"积蓄刚开始，力量不足，不宜进取。"},{"label":"九二","text":"舆说輹","trans":"车的车轴脱开。","anal":"主动停下，不强行前进，避免倾覆。"},{"label":"九三","text":"良马逐，利艰贞。日闲舆卫，利有攸往","trans":"良马竞相驰骋，利于艰难守正。日日练习车马防卫，利于前行。","anal":"积蓄充足，勤学苦练，做好准备再出发。"},{"label":"六四","text":"童牛之牿，元吉","trans":"给小牛装上横木防顶角，大吉。","anal":"在萌芽阶段就加以约束，防患于未然。"},{"label":"六五","text":"豮豕之牙，吉","trans":"阉割过的猪，虽有獠牙，不再凶暴，吉祥。","anal":"从根源化解刚猛之害，顺势教化。"},{"label":"上九","text":"何天之衢，亨","trans":"通向上天的大道，亨通。","anal":"德行才学积蓄圆满，大道开阔，通行无碍。"}],"yong":null},{"num":27,"name":"颐","pinyin":"yí","fullName":"山雷颐","binary":[1,0,0,0,0,1],"upper":{"sym":"☶","name":"艮","image":"山","pinyin":"gèn"},"lower":{"sym":"☳","name":"震","image":"雷","pinyin":"zhèn"},"guaci":{"text":"颐，贞吉。观颐，自求口实","trans":"颐，守正吉祥。观察颐养之道，自己谋求口粮、养活自己。","anal":"颐是颐养、养生。养身、养德，核心是自立，自食其力，修养身心。"},"lines":[{"label":"初九","text":"舍尔灵龟，观我朵颐，凶","trans":"舍弃自己灵龟般静定自养的本心，盯着别人鼓嘴进食，凶险。","anal":"羡慕别人所得，贪求外物，丧失自立本心。"},{"label":"六二","text":"颠颐，拂经，于丘颐，征凶","trans":"颠倒颐养之道，违背常理，向高处求供养，前进凶险。","anal":"本末倒置，向下养上、依附他人求供养，不可长久。"},{"label":"六三","text":"拂颐，贞凶，十年勿用，无攸利","trans":"违背颐养正道，守正也凶险，长久不可任用，没有好处。","anal":"以不正当方式谋生，长久有害。"},{"label":"六四","text":"颠颐，吉。虎视眈眈，其欲逐逐，无咎","trans":"颠倒颐养，吉祥。老虎紧盯，欲望不断，但是没有过错。","anal":"上位者向下养民，心怀警惕，持续养济众人。"},{"label":"六五","text":"拂经，居贞吉，不可涉大川","trans":"违背常理，安居守正吉祥，不可以冒险渡大河。","anal":"自身力量不足，依靠贤者养己，适合守静，不宜冒险。"},{"label":"上九","text":"由颐，厉吉，利涉大川","trans":"天下依靠他颐养，虽有危厉，吉祥，利于渡过大河。","anal":"担当养天下的重任，担责虽难，可成就大事。"}],"yong":null},{"num":28,"name":"大过","pinyin":"dà guò","fullName":"泽风大过","binary":[0,1,1,1,1,0],"upper":{"sym":"☱","name":"兑","image":"泽","pinyin":"duì"},"lower":{"sym":"☴","name":"巽","image":"风","pinyin":"xùn"},"guaci":{"text":"大过，栋桡，利有攸往，亨","trans":"大过，房梁弯曲。可以有所行动，亨通。","anal":"大过是大为过甚、负荷过重。局面非常特殊，需要非常之人担重任，风险很大。"},"lines":[{"label":"初六","text":"藉用白茅，无咎","trans":"用洁白茅草铺垫祭品，没有过错。","anal":"处境艰险，极度谨慎，恭敬自持。"},{"label":"九二","text":"枯杨生稊，老夫得其女妻，无不利","trans":"枯杨树长出新芽，年老男子娶年少妻子，没有不利。","anal":"衰旧之中生出新生之机，老树发新芽。"},{"label":"九三","text":"栋桡，凶","trans":"房梁弯曲，凶险。","anal":"支撑的主干不堪重负，即将崩塌。"},{"label":"九四","text":"栋隆，吉。有它吝","trans":"房梁隆起坚挺，吉祥。但是另有变故则有遗憾。","anal":"主干能承重，但是仍要提防意外。"},{"label":"九五","text":"枯杨生华，老妇得其士夫，无咎无誉","trans":"枯杨树开花，年老妇人得到年轻丈夫，无过错，也无美誉。","anal":"虚有繁华，根基难久，浮华短暂。"},{"label":"上六","text":"过涉灭顶，凶，无咎","trans":"涉水太深，淹没头顶，凶险；但本心为公，没有过错。","anal":"挺身而出承担危难，牺牲自身，志可嘉，结局凶险。"}],"yong":null},{"num":29,"name":"坎","pinyin":"kǎn","fullName":"习坎","binary":[0,1,0,0,1,0],"upper":{"sym":"☵","name":"坎","image":"水","pinyin":"kǎn"},"lower":{"sym":"☵","name":"坎","image":"水","pinyin":"kǎn"},"guaci":{"text":"习坎，有孚，维心亨，行有尚","trans":"重重险坎，心怀诚信，内心通达，行动会得到推崇。","anal":"坎为水，重重险难。身处接连险境，守住内心诚信，沉稳才能渡过难关。"},"lines":[{"label":"初六","text":"习坎，入于坎窞，凶","trans":"重重险坑，落入深坑底部，凶险。","anal":"一开始就深陷险境，难以脱身。"},{"label":"九二","text":"坎有险，求小得","trans":"险中有险，只求小有收获。","anal":"身处险中，目标不宜过大，先求小的收益自保。"},{"label":"六三","text":"来之坎坎，险且枕，入于坎窞，勿用","trans":"来去都是险坑，险难重重，落入深坑，不可行动。","anal":"进退皆险，只能静守，不可妄动。"},{"label":"六四","text":"樽酒，簋贰，用缶，纳约自牖，终无咎","trans":"一杯酒，两簋饭，用瓦器简朴盛放，从窗户进献简约信物，最终无咎。","anal":"险难之中，以诚相待，简约沟通，不重形式。"},{"label":"九五","text":"坎不盈，祇既平，无咎","trans":"险坑还没有填满，水位快要平齐，没有过错。","anal":"险难逐步平复，持续努力，不急于求成。"},{"label":"上六","text":"系用徽纆，置于丛棘，三岁不得，凶","trans":"用绳索捆绑，关在荆棘囚牢，多年不能解脱，凶险。","anal":"深陷罗网，长期困厄，难以脱身。"}],"yong":null},{"num":30,"name":"离","pinyin":"lí","fullName":"离为火","binary":[1,0,1,1,0,1],"upper":{"sym":"☲","name":"离","image":"火","pinyin":"lí"},"lower":{"sym":"☲","name":"离","image":"火","pinyin":"lí"},"guaci":{"text":"离，利贞，亨。畜牝牛，吉","trans":"离，利于守正，亨通。蓄养母牛（柔顺依附），吉祥。","anal":"离为火，光明、依附。光明需要依托载体，为人要守柔顺，依附正道。"},"lines":[{"label":"初九","text":"履错然，敬之无咎","trans":"脚步错乱，举止纷杂，心怀恭敬，就没有过错。","anal":"刚开始接触光明，纷乱不定，恭敬自持。"},{"label":"六二","text":"黄离，元吉","trans":"黄色附丽于光明，大吉。","anal":"居中守正，柔和光明，中道最美。"},{"label":"九三","text":"日昃之离，不鼓缶而歌，则大耋之嗟，凶","trans":"太阳西斜，光明将暮。不敲瓦缶自乐，就会有衰老悲叹，凶险。","anal":"盛极将暮，顺应时序，坦然接受衰老落幕。"},{"label":"九四","text":"突如其来如，焚如，死如，弃如","trans":"突然爆发，像烈火焚烧，毁灭、抛弃。","anal":"突如其来的祸变，火势猛烈，毁灭一切。"},{"label":"六五","text":"出涕沱若，戚嗟若，吉","trans":"泪流如雨，忧伤叹息，吉祥。","anal":"见灾祸而常怀忧惧，警惕自省，故而得吉。"},{"label":"上九","text":"王用出征，有嘉折首，获其匪丑，无咎","trans":"君王出征讨伐，嘉奖斩杀首恶，不滥杀胁从，没有过错。","anal":"光明照察，讨伐元凶，宽宥从犯，刚柔得当。"}],"yong":null},{"num":31,"name":"咸","pinyin":"xián","fullName":"泽山咸","binary":[0,0,1,1,1,0],"upper":{"sym":"☱","name":"兑","image":"泽","pinyin":"duì"},"lower":{"sym":"☶","name":"艮","image":"山","pinyin":"gèn"},"guaci":{"text":"咸，亨，利贞。取女吉","trans":"咸，亨通，利于守正。娶女子吉祥。","anal":"咸是感应、相通。男女相感、人心交感，真诚相互感应，重在无心而自然相通。"},"lines":[{"label":"初六","text":"咸其拇","trans":"感应在脚趾。","anal":"感应刚刚萌芽，微动，还没有大行动。"},{"label":"六二","text":"咸其腓，凶，居吉","trans":"感应在小腿，躁动凶险，安居不动吉祥。","anal":"感应生起，不可躁动冒进，宜静。"},{"label":"九三","text":"咸其股，执其随，往吝","trans":"感应在大腿，执意跟随别人，前往有遗憾。","anal":"盲目追随他人，没有主见，被动跟随。"},{"label":"九四","text":"贞吉悔亡，憧憧往来，朋从尔思","trans":"守正吉祥，悔恨消失。心神不定往来，朋友顺应你的想法。","anal":"以正道感应，不要私心杂念、胡思乱想。"},{"label":"九五","text":"咸其脢，无悔","trans":"感应在后背，没有悔恨。","anal":"感应内敛，不外露，沉静自持。"},{"label":"上六","text":"咸其辅颊舌","trans":"感应在口舌脸颊。","anal":"感应停留在言语口舌，虚浮，没有实质。"}],"yong":null},{"num":32,"name":"恒","pinyin":"héng","fullName":"雷风恒","binary":[0,1,1,1,0,0],"upper":{"sym":"☳","name":"震","image":"雷","pinyin":"zhèn"},"lower":{"sym":"☴","name":"巽","image":"风","pinyin":"xùn"},"guaci":{"text":"恒，亨，无咎，利贞，利有攸往","trans":"恒，亨通，没有过错，利于守正，利于前行。","anal":"恒是恒久、持之以恒。长久坚守正道，有恒心，持之以恒方能成事。"},"lines":[{"label":"初六","text":"浚恒，贞凶，无攸利","trans":"深求恒久，急于求成，守正也凶险，没有好处。","anal":"一开始就强求长久，逼迫太紧，适得其反。"},{"label":"九二","text":"悔亡","trans":"悔恨消失。","anal":"居中守中道，调整自身，长久之道贵在适度。"},{"label":"九三","text":"不恒其德，或承之羞，贞吝","trans":"不能长久坚守德行，有时会蒙受羞辱，守正也有遗憾。","anal":"德行摇摆不定，反复无常，自取羞辱。"},{"label":"九四","text":"田无禽","trans":"打猎没有猎物。","anal":"位置不当，空有恒心，方向不对，劳而无获。"},{"label":"六五","text":"恒其德，贞，妇人吉，夫子凶","trans":"恒久守德行，守正。妇人吉祥，男子凶险。","anal":"女子以柔顺恒久为正；男子一味顺从，缺少决断，不利。"},{"label":"上六","text":"振恒，凶","trans":"震动动荡，没有稳定，凶险。","anal":"长久动荡，不能安定，恒道彻底丧失。"}],"yong":null},{"num":33,"name":"遁","pinyin":"dùn","fullName":"天山遁","binary":[0,0,1,1,1,1],"upper":{"sym":"☰","name":"乾","image":"天","pinyin":"qián"},"lower":{"sym":"☶","name":"艮","image":"山","pinyin":"gèn"},"guaci":{"text":"遁，亨，小利贞","trans":"遁，亨通，小处利于守正。","anal":"遁是退避、隐退。大势不利的时候，懂得适时退让、抽身，不是懦弱，是智慧。"},"lines":[{"label":"初六","text":"遁尾，厉，勿用有攸往","trans":"退避落在末尾，有危险，不要有所行动。","anal":"退避太晚，危机已经临近，不宜行动。"},{"label":"六二","text":"执之用黄牛之革，莫之胜说","trans":"用黄牛皮的绳索捆住，无法挣脱。","anal":"心志坚定，牢牢守住本心，不被诱惑裹挟。"},{"label":"九三","text":"系遁，有疾厉，畜臣妾吉","trans":"牵挂牵绊，想退又舍不得，有疾患危险；蓄养仆从，小事吉祥。","anal":"心中牵挂名利，难以抽身，被拖累。"},{"label":"九四","text":"好遁，君子吉，小人否","trans":"欣然退避，君子吉祥，小人做不到。","anal":"君子可以放下喜爱之物，从容抽身。"},{"label":"九五","text":"嘉遁，贞吉","trans":"美好的退隐，守正吉祥。","anal":"时机合适，体面从容退身，恰到好处。"},{"label":"上九","text":"肥遁，无不利","trans":"宽裕自在地退隐，没有不利。","anal":"超然物外，毫无牵绊，自在远退。"}],"yong":null},{"num":34,"name":"大壮","pinyin":"dà zhuàng","fullName":"雷天大壮","binary":[1,1,1,1,0,0],"upper":{"sym":"☳","name":"震","image":"雷","pinyin":"zhèn"},"lower":{"sym":"☰","name":"乾","image":"天","pinyin":"qián"},"guaci":{"text":"大壮，利贞","trans":"大壮，利于守正。","anal":"大壮是阳气强盛、力量壮大。力量强了，更要守正克制，不能恃强逞暴。"},"lines":[{"label":"初九","text":"壮于趾，征凶，有孚","trans":"强盛在脚趾，贸然前进凶险，但是心怀诚信。","anal":"力量刚萌发，只有局部强盛，不可逞强进攻。"},{"label":"九二","text":"贞吉","trans":"守正吉祥。","anal":"居中守正，强而不逞，克制自持。"},{"label":"九三","text":"小人用壮，君子用罔，贞厉。羝羊触藩，羸其角","trans":"小人恃强斗狠，君子不逞刚强；守正也有危险。公羊顶撞篱笆，角被卡住。","anal":"恃强硬冲，容易卡在中间，进退两难。"},{"label":"九四","text":"贞吉，悔亡。藩决不羸，壮于大舆之輹","trans":"守正吉祥，悔恨消失。篱笆冲破，角不再被卡，强盛如同大车的车轴。","anal":"正道之强，可以冲破阻碍，力量坚实。"},{"label":"六五","text":"丧羊于易，无悔","trans":"在田畔丢失公羊，没有悔恨。","anal":"不强求刚强，坦然放下，不执着争强。"},{"label":"上六","text":"羝羊触藩，不能退，不能遂，无攸利，艰则吉","trans":"公羊顶撞篱笆，退不得、进不得，没有好处；在艰难中守正，可得吉祥。","anal":"逞强被困，进退两难，只能耐心熬过困境。"}],"yong":null},{"num":35,"name":"晋","pinyin":"jìn","fullName":"火地晋","binary":[0,0,0,1,0,1],"upper":{"sym":"☲","name":"离","image":"火","pinyin":"lí"},"lower":{"sym":"☷","name":"坤","image":"地","pinyin":"kūn"},"guaci":{"text":"晋，康侯用锡马蕃庶，昼日三接","trans":"晋，康侯得到君王赏赐众多车马，一天之内多次接见。","anal":"晋是晋升、上进。光明上升，德才兼备，稳步上进，得到赏识。"},"lines":[{"label":"初六","text":"晋如，摧如，贞吉。罔孚，裕无咎","trans":"前进，受挫折，守正吉祥。还没有取得信任，宽和从容，无咎。","anal":"刚开始上进，暂时受挫，不急于求信任，宽心自持。"},{"label":"六二","text":"晋如，愁如，贞吉。受兹介福，于其王母","trans":"前进，心中忧愁，守正吉祥。从祖母那里承受大福。","anal":"上进之路有忧愁，坚守正道，自有福佑。"},{"label":"六三","text":"众允，悔亡","trans":"众人信任认可，悔恨消失。","anal":"得到大家信服，上进之路顺畅。"},{"label":"九四","text":"晋如鼫鼠，贞厉","trans":"上进如同贪食的鼫鼠，守正也有危险。","anal":"上进却贪得无厌，德行不配位置，有隐患。"},{"label":"六五","text":"悔亡，失得勿恤，往吉，无不利","trans":"悔恨消失，不必计较得失，前行吉祥，无往不利。","anal":"光明在上，不计较得失，坦荡前进。"},{"label":"上九","text":"晋其角，维用伐邑，厉吉无咎，贞吝","trans":"上进到顶端，如同兽角，只能讨伐自己封邑内的叛乱；有危险，吉祥无过，守正也有遗憾。","anal":"到了高位，只适合对内整顿，不宜向外大肆进取。"}],"yong":null},{"num":36,"name":"明夷","pinyin":"míng yí","fullName":"地火明夷","binary":[1,0,1,0,0,0],"upper":{"sym":"☷","name":"坤","image":"地","pinyin":"kūn"},"lower":{"sym":"☲","name":"离","image":"火","pinyin":"lí"},"guaci":{"text":"明夷，利艰贞","trans":"明夷，在艰难之中守正有利。","anal":"明夷是光明受损、黑暗来临。正道被压抑，君子藏起光芒，在逆境坚守本心。"},"lines":[{"label":"初九","text":"明夷于飞，垂其翼。君子于行，三日不食，有攸往，主人有言","trans":"光明受伤的鸟儿飞翔，垂下翅膀。君子远行，多日吃不上饭，前往别处，主人会有责言。","anal":"黑暗初来，君子及早隐去，颠沛隐忍。"},{"label":"六二","text":"明夷，夷于左股，用拯马壮，吉","trans":"光明受伤，伤到左腿；借助强壮的马救援，吉祥。","anal":"受到伤害，但有外力相助，可以脱险。"},{"label":"九三","text":"明夷于南狩，得其大首，不可疾贞","trans":"光明受伤，向南征伐，擒获元凶；不可操之过急，守正。","anal":"黑暗之中，伺机除首恶，不可急于全部肃清。"},{"label":"六四","text":"入于左腹，获明夷之心，于出门庭","trans":"进入左侧腹地，洞悉黑暗伤害光明的本心，于是离开家门。","anal":"看透黑暗内情，果断抽身远避。"},{"label":"六五","text":"箕子之明夷，利贞","trans":"如同箕子佯狂藏明，利于守正。","anal":"大黑暗时代，藏起才智，守正自保，不显露锋芒。"},{"label":"上六","text":"不明晦，初登于天，后入于地","trans":"不发光而昏暗，起初高居天上，后来坠入地下。","anal":"黑暗的源头，起初看似光明，最终彻底覆灭。"}],"yong":null},{"num":37,"name":"家人","pinyin":"jiā rén","fullName":"风火家人","binary":[1,0,1,0,1,1],"upper":{"sym":"☴","name":"巽","image":"风","pinyin":"xùn"},"lower":{"sym":"☲","name":"离","image":"火","pinyin":"lí"},"guaci":{"text":"家人，利女贞","trans":"家人，女子守正吉祥。","anal":"家人是家庭。家庭内部各守本分，家风端正，家庭有序。"},"lines":[{"label":"初九","text":"闲有家，悔亡","trans":"在家之初就防范规矩，悔恨消失。","anal":"治家从一开始立规矩，防微杜渐。"},{"label":"六二","text":"无攸遂，在中馈，贞吉","trans":"不擅自做主，主持家中饮食内务，守正吉祥。","anal":"主妇守本分，料理家事，居中持家。"},{"label":"九三","text":"家人嗃嗃，悔厉，吉；妇子嘻嘻，终吝","trans":"家人严肃警戒，虽有悔惧，吉祥；妻儿嬉闹放纵，终有遗憾。","anal":"家规严，家道稳；过于嬉闹放任，家道衰败。"},{"label":"六四","text":"富家，大吉","trans":"使家庭富足，大吉。","anal":"勤俭持家，积蓄富足，家和富足。"},{"label":"九五","text":"王假有家，勿恤，吉","trans":"君王来到家中教化，不必忧虑，吉祥。","anal":"以德感化家人，家道端正。"},{"label":"上九","text":"有孚威如，终吉","trans":"心怀诚信，庄重有威严，最终吉祥。","anal":"治家以诚为本，辅以威严，长久安稳。"}],"yong":null},{"num":38,"name":"睽","pinyin":"kuí","fullName":"火泽睽","binary":[1,1,0,1,0,1],"upper":{"sym":"☲","name":"离","image":"火","pinyin":"lí"},"lower":{"sym":"☱","name":"兑","image":"泽","pinyin":"duì"},"guaci":{"text":"睽，小事吉","trans":"睽，做小事吉祥。","anal":"睽是背离、隔阂、意见不合。彼此有分歧，很难办大事，求同存异，从小事慢慢调和。"},"lines":[{"label":"初九","text":"悔亡。丧马勿逐，自复；见恶人，无咎","trans":"悔恨消失。丢失马匹不必追赶，自己会回来；见到恶人，没有过错。","anal":"有隔阂，不必强行追索，包容相见，静待自归。"},{"label":"九二","text":"遇主于巷，无咎","trans":"在小巷里意外遇见主人，没有过错。","anal":"隔阂之中，私下相遇沟通，化解矛盾。"},{"label":"六三","text":"见舆曳，其牛掣，其人天且劓，无初有终","trans":"看见车子被拖拽，牛被牵制，人受刺额割鼻之刑；开局不顺，结局尚可。","anal":"彼此互相牵制，矛盾重重，历经波折之后终能和解。"},{"label":"九四","text":"睽孤，遇元夫，交孚，厉无咎","trans":"睽隔孤独，遇到良善之人，彼此诚信相交，虽有危险，无咎。","anal":"孤立隔阂之时，遇见同道，以诚相交。"},{"label":"六五","text":"悔亡，厥宗噬肤，往何咎","trans":"悔恨消失，同族亲近如同咬嫩肉，前去有什么过错。","anal":"消除隔阂，亲近同道，前去相合。"},{"label":"上九","text":"睽孤，见豕负涂，载鬼一车，先张之弧，后说之弧，匪寇，婚媾，往遇雨则吉","trans":"睽隔孤独，看见满身泥污的猪，又看见一车鬼怪；先张弓，后放下弓。不是强盗，是求亲之人；前往遇雨冲洗尘埃，吉祥。","anal":"隔阂生出猜忌，看错对方；疑云散去，真相大白，矛盾化解。"}],"yong":null},{"num":39,"name":"蹇","pinyin":"jiǎn","fullName":"水山蹇","binary":[0,0,1,0,1,0],"upper":{"sym":"☵","name":"坎","image":"水","pinyin":"kǎn"},"lower":{"sym":"☶","name":"艮","image":"山","pinyin":"gèn"},"guaci":{"text":"蹇，利西南，不利东北。利见大人，贞吉","trans":"蹇，利于往西南平地，不利往东北险山。适合拜见有德之人，守正吉祥。","anal":"蹇是艰难、行路受阻。前路艰难，要寻找良师益友，不要硬闯险地。"},"lines":[{"label":"初六","text":"往蹇，来誉","trans":"前去艰难，回来得到赞誉。","anal":"不强行冒险前进，知难而退，得到肯定。"},{"label":"六二","text":"王臣蹇蹇，匪躬之故","trans":"君王臣子接连艰难，不是为自身私利。","anal":"为国事奔走，历尽艰难，大公无私。"},{"label":"九三","text":"往蹇，来反","trans":"前去艰难，返回来。","anal":"前路艰险，退回休整，不硬闯。"},{"label":"六四","text":"往蹇，来连","trans":"前去艰难，回来和同伴相连。","anal":"艰难之时，联合他人，结伴共渡难关。"},{"label":"九五","text":"大蹇，朋来","trans":"大难当头，志同道合之人前来相助。","anal":"身处巨大困境，同道之人来支援。"},{"label":"上六","text":"往蹇，来硕，吉。利见大人","trans":"前去艰难，回来有大收获，吉祥。适合拜见大德之人。","anal":"艰难走到尽头，回归而得大功，依靠贤德之人。"}],"yong":null},{"num":40,"name":"解","pinyin":"xiè","fullName":"雷水解","binary":[0,1,0,1,0,0],"upper":{"sym":"☳","name":"震","image":"雷","pinyin":"zhèn"},"lower":{"sym":"☵","name":"坎","image":"水","pinyin":"kǎn"},"guaci":{"text":"解，利西南，无所往，其来复吉。有攸往，夙吉","trans":"解，利于西南。没有目标就返回安居吉祥；如果要行动，趁早行动吉祥。","anal":"解是消散、解难。困境慢慢解开，压力释放，该休息就休息，该行动就要趁早。"},"lines":[{"label":"初六","text":"无咎","trans":"没有过错。","anal":"险难刚开始消散，安稳自持，无咎。"},{"label":"九二","text":"田获三狐，得黄矢，贞吉","trans":"打猎捕获多只狐狸，得到黄色箭矢，守正吉祥。","anal":"除去奸邪小人，守中道，刚直得当。"},{"label":"六三","text":"负且乘，致寇至，贞吝","trans":"背着财物又乘车，招引强盗到来，守正也有遗憾。","anal":"德不配位，炫耀财富，招致祸患。"},{"label":"九四","text":"解而拇，朋至斯孚","trans":"解开脚上的束缚，同道之人前来，彼此诚信。","anal":"解除牵绊，放开手脚，同道相聚。"},{"label":"六五","text":"君子维有解，吉；有孚于小人","trans":"君子得以解脱，吉祥；以诚信感化小人。","anal":"化解困局，诚信感化，宽宥小人。"},{"label":"上六","text":"公用射隼于高墉之上，获之，无不利","trans":"公侯在高墙上射猎猛隼，捕获它，无往不利。","anal":"除去盘踞高位的奸恶，一举清除祸患。"}],"yong":null},{"num":41,"name":"损","pinyin":"sǔn","fullName":"山泽损","binary":[1,1,0,0,0,1],"upper":{"sym":"☶","name":"艮","image":"山","pinyin":"gèn"},"lower":{"sym":"☱","name":"兑","image":"泽","pinyin":"duì"},"guaci":{"text":"损，有孚，元吉，无咎，可贞，利有攸往。曷之用？二簋可用享","trans":"损，心怀诚信，大吉，无过错，可以守正，利于前行。祭祀用什么？两簋简朴祭品就可以敬献。","anal":"损是减损、割舍。减损自身多余，补益不足；贵在诚信，不必铺张。损要适度，不可一味自损。"},"lines":[{"label":"初九","text":"已事遄往，无咎，酌损之","trans":"事情做完，迅速前往相助，没有过错，斟酌分寸减损。","anal":"主动助人，但量力而行，把握尺度。"},{"label":"九二","text":"利贞，征凶，弗损，益之","trans":"利于守正，贸然出征凶险；不必减损自己，反而增益对方。","anal":"自身本就不足，不可再自损，守本就是益。"},{"label":"六三","text":"三人行，则损一人；一人行，则得其友","trans":"三人同行，会有一人受损离去；一人独行，会遇到志同道合之友。","anal":"多则生分，专一易得同心。"},{"label":"六四","text":"损其疾，使遄有喜，无咎","trans":"减除自身疾患，迅速好转，可喜，无咎。","anal":"主动改过、除去自身弊病。"},{"label":"六五","text":"或益之十朋之龟，弗克违，元吉","trans":"有人送来价值十朋的大宝龟，无法推辞，大吉。","anal":"诚心自损修德，反而会得到丰厚增益。"},{"label":"上九","text":"弗损，益之，无咎，贞吉，利有攸往，得臣无家","trans":"不必减损，反而增益万物，无过错，守正吉祥，利于前行，得到天下贤臣，而不私其家。","anal":"损道至极，转为益，大公无私，普惠众人。"}],"yong":null},{"num":42,"name":"益","pinyin":"yì","fullName":"风雷益","binary":[1,0,0,0,1,1],"upper":{"sym":"☴","name":"巽","image":"风","pinyin":"xùn"},"lower":{"sym":"☳","name":"震","image":"雷","pinyin":"zhèn"},"guaci":{"text":"益，利有攸往，利涉大川","trans":"益，利于有所前往，利于渡过大河险难。","anal":"益是增益、助益。损上益下，施惠于民；行善助人才是长久增益。"},"lines":[{"label":"初九","text":"利用为大作，元吉，无咎","trans":"适合兴办大事，大吉，无过错。","anal":"得到增益，把握时机，兴办利民之事。"},{"label":"六二","text":"或益之十朋之龟，弗克违，永贞吉。王用享于帝，吉","trans":"有人送来十朋之龟，不可推辞，长久守正吉祥。君王以此祭祀天帝，吉祥。","anal":"厚福加身，常怀守正之心，敬天而行。"},{"label":"六三","text":"益之用凶事，无咎。有孚中行，告公用圭","trans":"增益用于救凶救灾，无过错。心怀诚信、守中道，执圭向公侯禀告。","anal":"增益用来救济危难，持信守礼。"},{"label":"六四","text":"中行，告公从，利用为依迁国","trans":"守中道，禀告公侯，获得听从，适合依托这个条件迁都安民。","anal":"秉持中道建言，获得信任，办成大事。"},{"label":"九五","text":"有孚惠心，勿问元吉。有孚惠我德","trans":"心怀诚信、惠泽他人，不必问，大吉。他人也以诚信感念我的恩德。","anal":"真心施惠，不求回报，人心归附。"},{"label":"上九","text":"莫益之，或击之，立心勿恒，凶","trans":"没有人来增益他，反而有人攻击他；心志没有恒常，凶险。","anal":"贪求增益、索取无度，终会被人厌弃。"}],"yong":null},{"num":43,"name":"夬","pinyin":"guài","fullName":"泽天夬","binary":[1,1,1,1,1,0],"upper":{"sym":"☱","name":"兑","image":"泽","pinyin":"duì"},"lower":{"sym":"☰","name":"乾","image":"天","pinyin":"qián"},"guaci":{"text":"夬，扬于王庭，孚号有厉。告自邑，不利即戎，利有攸往","trans":"夬，在王庭宣扬，诚信号召，存有警惕。向封邑通告，不宜立刻动武，利于正道前行。","anal":"夬是决断、清除小人。阳盛而要决去最后一阴，要公开、审慎，不可贸然动武。"},"lines":[{"label":"初九","text":"壮于前趾，往不胜为咎","trans":"强盛在前面脚趾，贸然前往，不能取胜就会有过失。","anal":"力量尚浅，不可逞强决断。"},{"label":"九二","text":"惕号，莫夜有戎，勿恤","trans":"警惕呼号，即使夜里有敌寇来袭，不必忧虑。","anal":"常备戒备，早有防备，可从容应对。"},{"label":"九三","text":"壮于頄，有凶。君子夬夬，独行遇雨，若濡有愠，无咎","trans":"刚强显露在脸上，有凶险。君子果决除奸，独自前行遇雨，沾湿身体、受人误解，终无过错。","anal":"除奸之心坚定，但锋芒外露容易招祸；虽遭误解，本心正直。"},{"label":"九四","text":"臀无肤，其行次且，牵羊悔亡，闻言不信","trans":"臀部皮肉受损，行走艰难；像牵羊一样顺势而行，悔恨消失；听到忠告却不肯相信。","anal":"自身有阻碍，行动困难，要顺势，不可固执不听劝。"},{"label":"九五","text":"苋陆夬夬，中行无咎","trans":"像斩除苋陆草一样果决清除，守中道而行，无过错。","anal":"居中持正，果断除奸，不过激。"},{"label":"上六","text":"无号，终有凶","trans":"不必呼号，终究有凶险。","anal":"被决断的小人，势穷力尽，难逃祸殃。"}],"yong":null},{"num":44,"name":"姤","pinyin":"gòu","fullName":"天风姤","binary":[0,1,1,1,1,1],"upper":{"sym":"☰","name":"乾","image":"天","pinyin":"qián"},"lower":{"sym":"☴","name":"巽","image":"风","pinyin":"xùn"},"guaci":{"text":"姤，女壮，勿用取女","trans":"姤，女子强盛，不要娶这样的女子。","anal":"姤是相遇、邂逅。一阴初生，阴邪悄然滋生；相遇要辨正邪，防范隐患萌芽。"},"lines":[{"label":"初六","text":"系于金柅，贞吉。有攸往，见凶，羸豕孚蹢躅","trans":"拴在金属刹车上，守正吉祥。如果放任前行，会有凶险；瘦弱的母猪，躁动不安。","anal":"阴邪初起，及时约束，防止蔓延。"},{"label":"九二","text":"包有鱼，无咎，不利宾","trans":"厨房里有鱼，无过错，不宜拿来招待外人。","anal":"偶遇之利，守在本分，不宜向外张扬。"},{"label":"九三","text":"臀无肤，其行次且，厉，无大咎","trans":"臀部皮肉受损，行走踉跄，有危险，但没有大过错。","anal":"进退两难，虽有困顿，没有大的过失。"},{"label":"九四","text":"包无鱼，起凶","trans":"厨房里没有鱼，生出凶险。","anal":"失去相遇的机缘，民心离散，祸由此起。"},{"label":"九五","text":"以杞包瓜，含章，有陨自天","trans":"用杞柳包裹瓜果，内含文采，好的际遇自天而降。","anal":"蕴才不露，静待机缘，不主动强求相遇。"},{"label":"上九","text":"姤其角，吝，无咎","trans":"在角落相遇，有所遗憾，没有大过错。","anal":"相遇在偏远之处，隔绝不通，难有作为，但无大害。"}],"yong":null},{"num":45,"name":"萃","pinyin":"cuì","fullName":"泽地萃","binary":[0,0,0,1,1,0],"upper":{"sym":"☱","name":"兑","image":"泽","pinyin":"duì"},"lower":{"sym":"☷","name":"坤","image":"地","pinyin":"kūn"},"guaci":{"text":"萃，亨。王假有庙，利见大人，亨，利贞。用大牲吉，利有攸往","trans":"萃，亨通。君王到宗庙祭祀，适合拜见大德之人，亨通，利于守正。用大的祭品祭祀吉祥，利于前行。","anal":"萃是聚集、会聚。众人相聚，贵在有德之人引领，以诚相聚，有序而不散乱。"},"lines":[{"label":"初六","text":"有孚不终，乃乱乃萃。若号，一握为笑，勿恤，往无咎","trans":"有诚信却不能坚持到底，纷乱之中勉强相聚。如果呼号求助，握手言欢，不必忧虑，前往无咎。","anal":"相聚之初心志不稳，坦诚沟通，可化解混乱。"},{"label":"六二","text":"引吉，无咎。孚乃利用禴","trans":"受人牵引而吉祥，无过错。心怀诚信，简约祭祀也能得福。","anal":"依托正道贤者相聚，以诚为本，不求奢华。"},{"label":"六三","text":"萃如，嗟如，无攸利。往无咎，小吝","trans":"相聚之时叹息忧愁，没有好处。前去相聚无过错，小有遗憾。","anal":"所聚非人，志同道合者稀少，难有大作为。"},{"label":"九四","text":"大吉，无咎","trans":"大吉，无过错。","anal":"得位而聚合众人，正道汇聚，大功有成。"},{"label":"九五","text":"萃有位，无咎。匪孚，元永贞，悔亡","trans":"居于上位聚合众人，无过错。如果还没有获得信任，长久守正，悔恨自消。","anal":"身居领导之位，以德慢慢取信于人。"},{"label":"上六","text":"赍咨涕洟，无咎","trans":"叹息流泪，无过错。","anal":"相聚将散，忧惧自省，不强行挽留，故无咎。"}],"yong":null},{"num":46,"name":"升","pinyin":"shēng","fullName":"地风升","binary":[0,1,1,0,0,0],"upper":{"sym":"☷","name":"坤","image":"地","pinyin":"kūn"},"lower":{"sym":"☴","name":"巽","image":"风","pinyin":"xùn"},"guaci":{"text":"升，元亨，用见大人，勿恤，南征吉","trans":"升，大通顺，适合拜见大德之人，不必忧虑，向南方进取吉祥。","anal":"升是上升、长进。积小成大，循序渐进，顺势上升，稳步成长。"},"lines":[{"label":"初六","text":"允升，大吉","trans":"诚信上进，大吉。","anal":"诚心向善，顺势上升，根基稳固。"},{"label":"九二","text":"孚乃利用禴，无咎","trans":"心怀诚信，简约祭祀也能获福，无过错。","anal":"上升途中，以诚立身，不必浮华。"},{"label":"九三","text":"升虚邑","trans":"上升进入空旷的城邑。","anal":"上升之路开阔，没有阻碍，顺势前行。"},{"label":"六四","text":"王用亨于岐山，吉，无咎","trans":"君王在岐山祭祀，吉祥，无过错。","anal":"上升而不忘敬守本分，以德行事。"},{"label":"六五","text":"贞吉，升阶","trans":"守正吉祥，像一步步登上台阶。","anal":"循序渐进，按次序晋升，不冒进。"},{"label":"上六","text":"冥升，利于不息之贞","trans":"昏昧地持续上升，利于永不停歇地守正。","anal":"上升到极点，仍要持续修德，不可昏然贪进。"}],"yong":null},{"num":47,"name":"困","pinyin":"kùn","fullName":"泽水困","binary":[0,1,0,1,1,0],"upper":{"sym":"☱","name":"兑","image":"泽","pinyin":"duì"},"lower":{"sym":"☵","name":"坎","image":"水","pinyin":"kǎn"},"guaci":{"text":"困，亨。贞，大人吉，无咎。有言不信","trans":"困，亨通。守正，大德之人吉祥，无过错。此时说的话，别人难以相信。","anal":"困是困厄、受穷。身处困境，君子守正不改；小人困则乱。困境之中言语难被采信，少说多守。"},"lines":[{"label":"初六","text":"臀困于株木，入于幽谷，三岁不觌","trans":"臀部困在枯木之下，进入幽深山谷，多年不能露面。","anal":"深陷困局，难以出头，宜静守。"},{"label":"九二","text":"困于酒食，朱绂方来，利用享祀。征凶，无咎","trans":"困在酒食应酬之中，荣禄将要到来，适合祭祀修德。贸然出征凶险，本身无过错。","anal":"物质不愁，但志向受困，不宜向外进取。"},{"label":"六三","text":"困于石，据于蒺藜，入于其宫，不见其妻，凶","trans":"困在石头前，背靠蒺藜，回到家中，见不到妻子，凶险。","anal":"进退皆难，内外交困，无处安身。"},{"label":"九四","text":"来徐徐，困于金车，吝，有终","trans":"缓缓而来，被华贵的车子困住，有遗憾，但有结局。","anal":"受外物牵绊，进展缓慢，终究可以脱困。"},{"label":"九五","text":"劓刖，困于赤绂，乃徐有说，利用祭祀","trans":"受割鼻断足之刑般的困厄，困在禄位之中，慢慢才能解脱，适合祭祀修德。","anal":"身居高位而受困，隐忍修德，等待转机。"},{"label":"上六","text":"困于葛藟，于臲卼，曰动悔有悔，征吉","trans":"被藤蔓缠绕，惶惶不安；一动就生悔，懂得悔改，进取则吉祥。","anal":"困到极点，反省改过，才可以走出困局。"}],"yong":null},{"num":48,"name":"井","pinyin":"jǐng","fullName":"水风井","binary":[0,1,1,0,1,0],"upper":{"sym":"☵","name":"坎","image":"水","pinyin":"kǎn"},"lower":{"sym":"☴","name":"巽","image":"风","pinyin":"xùn"},"guaci":{"text":"井，改邑不改井，无丧无得，往来井井。汔至，亦未繘井，羸其瓶，凶","trans":"井，村落可以迁移，井不能移动；井水不会因取用而减少，也不会自满增多。人们往来取水。水快要到井口，还没把井绳提上来，水瓶倾覆，凶险。","anal":"井代表养人、恒久不变的德行。井养万物，修德之人长久利人；做事贵在善始善终，功亏一篑则凶。"},"lines":[{"label":"初六","text":"井泥不食，旧井无禽","trans":"井底淤泥浑浊，水不能饮用；老旧荒井，连飞鸟都不来。","anal":"德行污浊，废弃无用，无人归附。"},{"label":"九二","text":"井谷射鲋，瓮敝漏","trans":"井底缝隙只有小鱼，取水的瓦瓮破漏。","anal":"有才而不得施展，器具破损，难以养人。"},{"label":"九三","text":"井渫不食，为我心恻，可用汲，王明，并受其福","trans":"井水淘干净了，却没人饮用，令人惋惜；井水可以汲取，君王明察，大家一同得福。","anal":"贤才被埋没，希望上位者识才任用。"},{"label":"六四","text":"井甃，无咎","trans":"修砌井壁，无过错。","anal":"自修德行，修养自身，不急求为人所用。"},{"label":"九五","text":"井冽，寒泉食","trans":"井水清澈甘凉，泉水可供饮用。","anal":"德行纯粹，贤才在位，滋养众人。"},{"label":"上六","text":"井收勿幕，有孚元吉","trans":"井修好，不必盖上井盖，心怀诚信，大吉。","anal":"养德而普惠众人，开放利人，不求私藏。"}],"yong":null},{"num":49,"name":"革","pinyin":"gé","fullName":"泽火革","binary":[1,0,1,1,1,0],"upper":{"sym":"☱","name":"兑","image":"泽","pinyin":"duì"},"lower":{"sym":"☲","name":"离","image":"火","pinyin":"lí"},"guaci":{"text":"革，巳日乃孚，元亨，利贞，悔亡","trans":"革，到了合适时日，变革才会获得信任；大通顺，利于守正，悔恨消失。","anal":"革是变革、革新。变革不能仓促，时机成熟、取信于人方可推行；变革要合乎正道。"},"lines":[{"label":"初九","text":"巩用黄牛之革","trans":"用黄牛皮牢牢捆住，不可轻动。","anal":"变革之初，根基不稳，不可贸然革新。"},{"label":"六二","text":"巳日乃革之，征吉，无咎","trans":"时机成熟，推行变革，进取吉祥，无过错。","anal":"时机已到，顺势变革。"},{"label":"九三","text":"征凶，贞厉。革言三就，有孚","trans":"贸然进取凶险，守正也有危险。变革的主张反复审定，获得信任。","anal":"变革方案要多次论证，不能急于推进。"},{"label":"九四","text":"悔亡，有孚改命，吉","trans":"悔恨消失，凭诚信变革旧命，吉祥。","anal":"取得信任，完成关键变革。"},{"label":"九五","text":"大人虎变，未占，有孚","trans":"大德之人变革，如猛虎换毛，焕然一新，不用占卜，众人信服。","anal":"上位者推行变革，光明正大，气象一新。"},{"label":"上六","text":"君子豹变，小人革面。征凶，居贞吉","trans":"君子像豹子换纹，修养革新；小人只是表面改变。贸然进取凶险，安居守正吉祥。","anal":"变革后期，上层修德，下层顺从；大局已定，不宜再激进改动。"}],"yong":null},{"num":50,"name":"鼎","pinyin":"dǐng","fullName":"火风鼎","binary":[0,1,1,1,0,1],"upper":{"sym":"☲","name":"离","image":"火","pinyin":"lí"},"lower":{"sym":"☴","name":"巽","image":"风","pinyin":"xùn"},"guaci":{"text":"鼎，元吉，亨","trans":"鼎，大吉，亨通。","anal":"鼎为立国之器，象征养贤、承新、稳固基业。鼎承新物，养贤才，稳固秩序。"},"lines":[{"label":"初六","text":"鼎颠趾，利出否，得妾以其子，无咎","trans":"鼎翻倒，鼎足朝上，利于倒出脏东西；如同妾生子而被接纳，无过错。","anal":"先除旧秽，才能纳新，看似颠覆，实则清理弊病。"},{"label":"九二","text":"鼎有实，我仇有疾，不我能即，吉","trans":"鼎中盛满食物，我的对手有隐患，不能来侵扰我，吉祥。","anal":"自身充实有才，小人难以加害。"},{"label":"九三","text":"鼎耳革，其行塞，雉膏不食。方雨亏悔，终吉","trans":"鼎耳损坏，移动受阻，美味的雉肉不能食用。等到下雨，消解悔恨，最终吉祥。","anal":"有才而通道受阻，静待时机，终有转机。"},{"label":"九四","text":"鼎折足，覆公餗，其形渥，凶","trans":"鼎足折断，倾覆公侯的美食，汤汁沾污，凶险。","anal":"力小任重，不堪承担大任，败坏大事。"},{"label":"六五","text":"鼎黄耳，金铉，利贞","trans":"鼎有黄色的耳，金属提环，利于守正。","anal":"中道得位，有贤才辅佐，稳固可靠。"},{"label":"上九","text":"鼎玉铉，大吉，无不利","trans":"鼎配有玉质提环，大吉，无往不利。","anal":"刚柔相济，德才兼备，鼎道大成。"}],"yong":null},{"num":51,"name":"震","pinyin":"zhèn","fullName":"震为雷","binary":[1,0,0,1,0,0],"upper":{"sym":"☳","name":"震","image":"雷","pinyin":"zhèn"},"lower":{"sym":"☳","name":"震","image":"雷","pinyin":"zhèn"},"guaci":{"text":"震，亨。震来虩虩，笑言哑哑。震惊百里，不丧匕鬯","trans":"震，亨通。惊雷袭来，惶恐戒备；之后安然谈笑。雷声震惊百里，主祭之人不失祭器。","anal":"震是震动、惊雷。遇变故能戒惧自省，虽有惊吓，不失本心，镇定自持。"},"lines":[{"label":"初九","text":"震来虩虩，后笑言哑哑，吉","trans":"惊雷初来惶恐，之后安然谈笑，吉祥。","anal":"懂得戒惧，之后从容安定。"},{"label":"六二","text":"震来厉，亿丧贝，跻于九陵，勿逐，七日得","trans":"惊雷来袭有危险，丧失财货，登上高陵躲避；不必追逐，七天之后失物复得。","anal":"变故来临，财物损失，放下追逐，静待复原。"},{"label":"六三","text":"震苏苏，震行无眚","trans":"震动之时惶恐不安，因震动而警醒修省，没有灾祸。","anal":"借着震动警醒自己，改过避祸。"},{"label":"九四","text":"震遂泥","trans":"震动之后陷入泥沼。","anal":"受震动而意志消沉，难以振作。"},{"label":"六五","text":"震往来厉，亿无丧，有事","trans":"震动来去都有危险，大体上不会丧失根本，仍要持续戒备。","anal":"变故反复，守住根本，持续谨慎。"},{"label":"上六","text":"震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。婚媾有言","trans":"震动之时畏缩发抖，目光惊惶，进取凶险。震动还没落到自身，先落在邻居身上，无过错；婚嫁之事会有闲言。","anal":"见邻遭祸而提前戒备，可自保，但人际难免非议。"}],"yong":null},{"num":52,"name":"艮","pinyin":"gèn","fullName":"艮为山","binary":[0,0,1,0,0,1],"upper":{"sym":"☶","name":"艮","image":"山","pinyin":"gèn"},"lower":{"sym":"☶","name":"艮","image":"山","pinyin":"gèn"},"guaci":{"text":"艮其背，不获其身，行其庭，不见其人，无咎","trans":"止于背部，不触及自身私欲；行走庭院，如同不见其人，无过错。","anal":"艮是止、克制。知止，止于当止之处，克制私欲，内心安定。"},"lines":[{"label":"初六","text":"艮其趾，无咎，利永贞","trans":"止住脚趾，无过错，利于长久守正。","anal":"在行动之初就知止，防微杜渐。"},{"label":"六二","text":"艮其腓，不拯其随，其心不快","trans":"止住小腿，不能追随上面的人，心中不快。","anal":"被迫停止，身不由己，内心郁结。"},{"label":"九三","text":"艮其限，列其夤，厉薰心","trans":"止住腰胯，撕裂脊背，危险如同烈火熏心。","anal":"强行压抑、硬止，身心受损，过犹不及。"},{"label":"六四","text":"艮其身，无咎","trans":"止住自身，约束自己，无过错。","anal":"自我约束，收敛私欲。"},{"label":"六五","text":"艮其辅，言有序，悔亡","trans":"止住口舌，说话有条理，悔恨消失。","anal":"慎言，言语有分寸。"},{"label":"上九","text":"敦艮，吉","trans":"敦厚知止，吉祥。","anal":"根基深厚，长久守止，德行大成。"}],"yong":null},{"num":53,"name":"渐","pinyin":"jiàn","fullName":"风山渐","binary":[0,0,1,0,1,1],"upper":{"sym":"☴","name":"巽","image":"风","pinyin":"xùn"},"lower":{"sym":"☶","name":"艮","image":"山","pinyin":"gèn"},"guaci":{"text":"渐，女归吉，利贞","trans":"渐，女子出嫁吉祥，利于守正。","anal":"渐是渐进、循序渐进。如同女子出嫁，一步步按次序，不急于求成。"},"lines":[{"label":"初六","text":"鸿渐于干，小子厉，有言，无咎","trans":"鸿雁飞到水边，幼童有危险，受到非议，无大过错。","anal":"渐进之初，地位低微，难免非议，稳步前行。"},{"label":"六二","text":"鸿渐于磐，饮食衎衎，吉","trans":"鸿雁飞到磐石上，安然饮食喜乐，吉祥。","anal":"渐进到安稳之地，处境安定。"},{"label":"九三","text":"鸿渐于陆，夫征不复，妇孕不育，凶；利御寇","trans":"鸿雁飞到高地，丈夫出征不回，妇女怀孕而流产，凶险；适合抵御寇贼。","anal":"渐进失度，越过本分，破坏安稳。"},{"label":"六四","text":"鸿渐于木，或得其桷，无咎","trans":"鸿雁飞到树上，或许找到平整枝桠栖息，无过错。","anal":"处境虽不安稳，找到安身之处，谨慎自保。"},{"label":"九五","text":"鸿渐于陵，妇三岁不孕，终莫之胜，吉","trans":"鸿雁飞到山陵，妇人多年不孕，终究无人能破坏，吉祥。","anal":"渐进之路漫长，历经等待，终得如愿。"},{"label":"上九","text":"鸿渐于陆，其羽可用为仪，吉","trans":"鸿雁飞到高地，羽毛可以作为礼仪仪仗，吉祥。","anal":"渐进大成，德行高洁，为人表率。"}],"yong":null},{"num":54,"name":"归妹","pinyin":"guī mèi","fullName":"雷泽归妹","binary":[1,1,0,1,0,0],"upper":{"sym":"☳","name":"震","image":"雷","pinyin":"zhèn"},"lower":{"sym":"☱","name":"兑","image":"泽","pinyin":"duì"},"guaci":{"text":"归妹，征凶，无攸利","trans":"归妹，贸然进取凶险，没有好处。","anal":"归妹是女子出嫁，婚嫁之事。本是正理，但要守礼；不合礼制的婚嫁，难以长久。"},"lines":[{"label":"初九","text":"归妹以娣，跛能履，征吉","trans":"以陪嫁的身份出嫁，如同跛脚却能行走，进取吉祥。","anal":"侧室陪嫁，本分守柔，虽有缺憾，守分得吉。"},{"label":"九二","text":"眇能视，利幽人之贞","trans":"眼盲却勉强能看，适合隐者守正。","anal":"处境有缺憾，守静自持，不向外求。"},{"label":"六三","text":"归妹以须，反归以娣","trans":"待嫁女子等待，最后反倒作为陪嫁回去。","anal":"期待过高，名分落空，降格相从。"},{"label":"九四","text":"归妹愆期，迟归有时","trans":"出嫁延误佳期，推迟出嫁，等待合适时机。","anal":"良缘未至，耐心等待，不勉强出嫁。"},{"label":"六五","text":"帝乙归妹，其君之袂不如其娣之袂良，月几望，吉","trans":"帝乙嫁女，正妻的衣饰反而不如陪嫁的华丽；月亮将近圆满，吉祥。","anal":"贵而不张扬，重德行而轻外表。"},{"label":"上六","text":"女承筐无实，士刲羊无血，无攸利","trans":"女子捧着筐子，里面空无一物；男子杀羊，不见血，没有好处。","anal":"婚嫁有名无实，仪式虚设，难成夫妇之实。"}],"yong":null},{"num":55,"name":"丰","pinyin":"fēng","fullName":"雷火丰","binary":[1,0,1,1,0,0],"upper":{"sym":"☳","name":"震","image":"雷","pinyin":"zhèn"},"lower":{"sym":"☲","name":"离","image":"火","pinyin":"lí"},"guaci":{"text":"丰，亨。王假之，勿忧，宜日中","trans":"丰，亨通。君王可以达到丰大之境，不必忧虑，宜如日在中天，光明盛大。","anal":"丰是丰盛、盛大。鼎盛之时，光明普照；盛极必衰，要警惕昏暗来临。"},"lines":[{"label":"初九","text":"遇其配主，虽旬无咎，往有尚","trans":"遇到相配的主人，十天之内没有过错，前行会得到推崇。","anal":"志同道合，相遇相助，共图丰大。"},{"label":"六二","text":"丰其蔀，日中见斗，往得疑疾，有孚发若，吉","trans":"光明被大帷幕遮蔽，正午看见星斗；前去会被猜疑，心怀诚信去开启，吉祥。","anal":"盛大之中昏暗滋生，以诚破除蒙蔽。"},{"label":"九三","text":"丰其沛，日中见沫，折其右肱，无咎","trans":"光明被厚幕遮蔽，正午看见微光小星；折断右臂，无过错。","anal":"黑暗加剧，损伤自身，守正自保，不妄动。"},{"label":"九四","text":"丰其蔀，日中见斗，遇其夷主，吉","trans":"光明被帷幕遮蔽，正午见星斗；遇到平等相合的主人，吉祥。","anal":"昏暗之时，遇见同道，互相扶持。"},{"label":"六五","text":"来章，有庆誉，吉","trans":"招纳贤才，彰显光彩，有喜庆美誉，吉祥。","anal":"鼎盛之时，招揽贤才，增益光明。"},{"label":"上六","text":"丰其屋，蔀其家，窥其户，阒其无人，三岁不觌，凶","trans":"把房屋修得高大，遮蔽家室；从门缝窥探，寂静无人，多年不见人影，凶险。","anal":"自恃盛大，隔绝世人，闭门自蔽，衰败来临。"}],"yong":null},{"num":56,"name":"旅","pinyin":"lǚ","fullName":"火山旅","binary":[0,0,1,1,0,1],"upper":{"sym":"☲","name":"离","image":"火","pinyin":"lí"},"lower":{"sym":"☶","name":"艮","image":"山","pinyin":"gèn"},"guaci":{"text":"旅，小亨，旅贞吉","trans":"旅，小有亨通，行旅在外，守正吉祥。","anal":"旅是羁旅、漂泊在外。旅居他乡，没有根基，宜谦卑谨慎，不可张扬。"},"lines":[{"label":"初六","text":"旅琐琐，斯其所取灾","trans":"行旅之人猥琐计较，这是自取灾祸。","anal":"漂泊在外，心胸狭隘，招人嫌恶。"},{"label":"六二","text":"旅即次，怀其资，得童仆贞","trans":"旅人住进客舍，带着资财，得到忠心童仆，守正。","anal":"旅居安稳，有资财、有可靠帮手，安稳自持。"},{"label":"九三","text":"旅焚其次，丧其童仆，贞厉","trans":"旅舍被火烧，失去童仆，守正也有危险。","anal":"傲慢失度，失去依靠，遭遇祸患。"},{"label":"九四","text":"旅于处，得其资斧，我心不快","trans":"旅人暂居一处，得到钱财兵器，心中不快。","anal":"虽有财物，但漂泊无根，内心不安。"},{"label":"六五","text":"射雉，一矢亡，终以誉命","trans":"射野鸡，丢失一支箭，最终得到荣誉爵命。","anal":"小有损失，终获美名。"},{"label":"上九","text":"鸟焚其巢，旅人先笑后号咷。丧牛于易，凶","trans":"鸟巢被火烧，旅人先欢喜而后大哭；在田畔丢失牛，凶险。","anal":"居高位而骄纵，得意之后大祸临头。"}],"yong":null},{"num":57,"name":"巽","pinyin":"xùn","fullName":"巽为风","binary":[0,1,1,0,1,1],"upper":{"sym":"☴","name":"巽","image":"风","pinyin":"xùn"},"lower":{"sym":"☴","name":"巽","image":"风","pinyin":"xùn"},"guaci":{"text":"巽，小亨，利有攸往，利见大人","trans":"巽，小有亨通，利于前行，适合拜见大德之人。","anal":"巽是顺从、谦逊、随风而入。谦逊顺从不是盲从，顺于正道，入而教化。"},"lines":[{"label":"初六","text":"进退，利武人之贞","trans":"犹豫进退不定，适合勇武之人守正。","anal":"心志摇摆，要坚定自持。"},{"label":"九二","text":"巽在床下，用史巫纷若，吉，无咎","trans":"谦卑伏在床下，祝史巫祝纷纷祷告，吉祥，无过错。","anal":"极度谦卑，诚敬沟通，以信感通。"},{"label":"九三","text":"频巽，吝","trans":"反复勉强顺从，有遗憾。","anal":"内心不情愿，一味顺从，没有主见。"},{"label":"六四","text":"悔亡，田获三品","trans":"悔恨消失，打猎收获多种猎物。","anal":"顺承正道，有所收获，建功得利。"},{"label":"九五","text":"贞吉，悔亡，无不利。无初有终。先庚三日，后庚三日，吉","trans":"守正吉祥，悔恨消失，无往不利。开局艰难，有好结局。庚日前三日谋划，庚日后三日推行，吉祥。","anal":"推行政令，预先谋划，择时实施。"},{"label":"上九","text":"巽在床下，丧其资斧，贞凶","trans":"谦卑伏在床下，丧失财资利器，守正也凶险。","anal":"谦卑过头，丧失底气与原则。"}],"yong":null},{"num":58,"name":"兑","pinyin":"duì","fullName":"兑为泽","binary":[1,1,0,1,1,0],"upper":{"sym":"☱","name":"兑","image":"泽","pinyin":"duì"},"lower":{"sym":"☱","name":"兑","image":"泽","pinyin":"duì"},"guaci":{"text":"兑，亨，利贞","trans":"兑，亨通，利于守正。","anal":"兑是喜悦、和悦。和悦待人，但是要守正道，不可谄媚取悦。"},"lines":[{"label":"初九","text":"和兑，吉","trans":"平和喜悦，吉祥。","anal":"发自本心，自然和悦，不刻意讨好。"},{"label":"九二","text":"孚兑，吉，悔亡","trans":"诚信带来喜悦，吉祥，悔恨消失。","anal":"以诚相待，和悦发自真心。"},{"label":"六三","text":"来兑，凶","trans":"主动前来讨好取悦，凶险。","anal":"刻意谄媚，为求喜悦而迎合他人。"},{"label":"九四","text":"商兑，未宁，介疾有喜","trans":"商量和悦之事，尚未安定；隔绝邪佞取悦，转为可喜。","anal":"分辨正邪，不与谄媚之人同流。"},{"label":"九五","text":"孚于剥，有厉","trans":"信任那些伤害正道的小人，有危险。","anal":"被甜言和悦迷惑，亲近奸邪。"},{"label":"上六","text":"引兑","trans":"引诱他人一同喜悦。","anal":"引诱取乐，劝人嬉游，没有原则。"}],"yong":null},{"num":59,"name":"涣","pinyin":"huàn","fullName":"风水涣","binary":[0,1,0,0,1,1],"upper":{"sym":"☴","name":"巽","image":"风","pinyin":"xùn"},"lower":{"sym":"☵","name":"坎","image":"水","pinyin":"kǎn"},"guaci":{"text":"涣，亨。王假有庙，利涉大川，利贞","trans":"涣，亨通。君王到宗庙祭祀，利于渡过大河险难，利于守正。","anal":"涣是涣散、离散。涣散之时，凝聚人心，拯救涣散，破除隔阂。"},"lines":[{"label":"初六","text":"用拯马壮，吉","trans":"借助强壮的马拯救，吉祥。","anal":"涣散初起，借助外力及时挽救。"},{"label":"九二","text":"涣奔其机，悔亡","trans":"涣散之时奔向安稳凭靠之处，悔恨消失。","anal":"动乱涣散，寻得依托，安定自身。"},{"label":"六三","text":"涣其躬，无悔","trans":"散去自身的私欲，没有悔恨。","anal":"放下小我，为公而忘私。"},{"label":"六四","text":"涣其群，元吉。涣有丘，匪夷所思","trans":"散去小团体，大吉。涣散之后凝聚成山丘般的大集体，超乎常人所想。","anal":"破除小圈子，凝聚大众。"},{"label":"九五","text":"涣汗其大号，涣王居，无咎","trans":"像汗水发散一样，发布盛大号令；疏散王宫积蓄，普惠众人，无过错。","anal":"君王推恩散财，政令广布。"},{"label":"上九","text":"涣其血，去逖出，无咎","trans":"散去忧患伤害，远离祸患，无过错。","anal":"远离灾祸，彻底脱离危险。"}],"yong":null},{"num":60,"name":"节","pinyin":"jié","fullName":"水泽节","binary":[1,1,0,0,1,0],"upper":{"sym":"☵","name":"坎","image":"水","pinyin":"kǎn"},"lower":{"sym":"☱","name":"兑","image":"泽","pinyin":"duì"},"guaci":{"text":"节，亨。苦节不可贞","trans":"节，亨通。过分刻苦的节制，不可长久固守。","anal":"节是节制、分寸、节度。凡事有度，节制适中为美；苦节压抑太过，难以持久。"},"lines":[{"label":"初九","text":"不出户庭，无咎","trans":"不走出内院门庭，无过错。","anal":"懂得节制，慎言慎行，不妄出。"},{"label":"九二","text":"不出门庭，凶","trans":"不肯走出大门，凶险。","anal":"节制过头，自我封闭，该动不动。"},{"label":"六三","text":"不节若，则嗟若，无咎","trans":"不知节制，之后就会叹息悔恨，无大过错。","anal":"放纵无度，尝到苦头才后悔。"},{"label":"六四","text":"安节，亨","trans":"安然节制，亨通。","anal":"自然而然守节度，不勉强。"},{"label":"九五","text":"甘节，吉，往有尚","trans":"甘美的节制，吉祥，前行受人推崇。","anal":"节制适度，恰到好处，不压抑、不放纵。"},{"label":"上六","text":"苦节，贞凶，悔亡","trans":"过分刻苦节制，守正也凶险；若能醒悟，悔恨可消。","anal":"苦节难久，压抑过度，不可长久。"}],"yong":null},{"num":61,"name":"中孚","pinyin":"zhōng fú","fullName":"风泽中孚","binary":[1,1,0,0,1,1],"upper":{"sym":"☴","name":"巽","image":"风","pinyin":"xùn"},"lower":{"sym":"☱","name":"兑","image":"泽","pinyin":"duì"},"guaci":{"text":"中孚，豚鱼吉，利涉大川，利贞","trans":"心中诚信，连豚鱼这类微物都能感化，吉祥；利于渡过大河，利于守正。","anal":"中孚是内心至诚。发自内心的诚信，可以感化万物，以诚为本。"},"lines":[{"label":"初九","text":"虞吉，有它不燕","trans":"安守诚信则吉祥，另有他念就不得安宁。","anal":"初心专一，不生杂念。"},{"label":"九二","text":"鸣鹤在阴，其子和之。我有好爵，吾与尔靡之","trans":"鹤在树荫鸣叫，小鹤应声相和。我有美酒，与你一同分享。","anal":"至诚相通，同声相应，不必言语。"},{"label":"六三","text":"得敌，或鼓或罢，或泣或歌","trans":"遇到对手，时而击鼓进攻，时而休战，时而悲泣，时而欢歌。","anal":"心志不定，诚信不专，情绪摇摆。"},{"label":"六四","text":"月几望，马匹亡，无咎","trans":"月亮将近圆满，良马失去同伴，无过错。","anal":"舍弃次要的同伴，专一追随正道。"},{"label":"九五","text":"有孚挛如，无咎","trans":"诚信相连，彼此紧扣，无过错。","anal":"上下以诚相连，同心同德。"},{"label":"上九","text":"翰音登于天，贞凶","trans":"鸡鸣之声飞上天空，守正也凶险。","anal":"虚声远扬，有名无实，诚信枯竭。"}],"yong":null},{"num":62,"name":"小过","pinyin":"xiǎo guò","fullName":"雷山小过","binary":[0,0,1,1,0,0],"upper":{"sym":"☳","name":"震","image":"雷","pinyin":"zhèn"},"lower":{"sym":"☶","name":"艮","image":"山","pinyin":"gèn"},"guaci":{"text":"小过，亨，利贞。可小事，不可大事。飞鸟遗之音，不宜上，宜下，大吉","trans":"小有过越，亨通，利于守正。可以做小事，不可做大事。飞鸟留下鸣声，不宜向上高飞，宜向下安居，大吉。","anal":"小过是小有逾越。小事可以变通，大事不可越轨；宜收敛，不宜向上逞强。"},"lines":[{"label":"初六","text":"飞鸟以凶","trans":"飞鸟向上高飞，招致凶险。","anal":"一味向上进取，不知收敛。"},{"label":"六二","text":"过其祖，遇其妣；不及其君，遇其臣，无咎","trans":"越过祖父，遇见祖母；不冒犯君主，遇见贤臣，无过错。","anal":"小有逾越，守分寸，不冒犯上位。"},{"label":"九三","text":"弗过防之，从或戕之，凶","trans":"没有越分，也要防备；放纵不加防范，会被伤害，凶险。","anal":"要提前戒备，不可大意。"},{"label":"九四","text":"无咎，弗过遇之。往厉必戒，勿用永贞","trans":"无过错，不必主动越分，顺势相遇。前往有危险，必须警戒，不可固守不变。","anal":"不主动求过，见机行事，常怀警惕。"},{"label":"六五","text":"密云不雨，自我西郊。公弋取彼在穴","trans":"浓云密布却不下雨，云起西郊。公侯射取穴中的猎物。","anal":"时机不足，难以大有作为，只可做小事。"},{"label":"上六","text":"弗遇过之，飞鸟离之，凶，是谓灾眚","trans":"没有相遇，强行越分；飞鸟落入罗网，凶险，这是自取灾祸。","anal":"过度越界，不知止，自取祸患。"}],"yong":null},{"num":63,"name":"既济","pinyin":"jì jì","fullName":"水火既济","binary":[1,0,1,0,1,0],"upper":{"sym":"☵","name":"坎","image":"水","pinyin":"kǎn"},"lower":{"sym":"☲","name":"离","image":"火","pinyin":"lí"},"guaci":{"text":"既济，亨，小利贞。初吉，终乱","trans":"既济，亨通，小事利于守正。开始吉祥，末尾容易混乱。","anal":"既济是已经成功、事成。万事已经完成，但是成功之后极易懈怠生乱，守成更难。"},"lines":[{"label":"初九","text":"曳其轮，濡其尾，无咎","trans":"拉住车轮，沾湿尾巴，无过错。","anal":"渡河之初，谨慎约束，防止倾覆。"},{"label":"六二","text":"妇丧其茀，勿逐，七日得","trans":"妇人丢失车帘，不必追寻，七天之后失而复得。","anal":"事成之后，小失不必计较，静待自回。"},{"label":"九三","text":"高宗伐鬼方，三年克之，小人勿用","trans":"高宗讨伐鬼方，三年才攻克；不可任用小人。","anal":"大功来之不易，平定之后，警惕小人。"},{"label":"六四","text":"繻有衣袽，终日戒","trans":"华美布料会变成破絮，整日戒备。","anal":"盛时常怀戒备，防备衰败。"},{"label":"九五","text":"东邻杀牛，不如西邻之禴祭，实受其福","trans":"东边邻居杀牛厚祭，不如西边邻居简约祭祀，诚心才得福。","anal":"贵在诚心，不在于祭品丰厚。"},{"label":"上六","text":"濡其首，厉","trans":"河水沾湿头部，危险。","anal":"成功之后骄傲自满，最终倾覆。"}],"yong":null},{"num":64,"name":"未济","pinyin":"wèi jì","fullName":"火水未济","binary":[0,1,0,1,0,1],"upper":{"sym":"☲","name":"离","image":"火","pinyin":"lí"},"lower":{"sym":"☵","name":"坎","image":"水","pinyin":"kǎn"},"guaci":{"text":"未济，亨。小狐汔济，濡其尾，无攸利","trans":"未济，亨通。小狐狸快要渡过河，沾湿尾巴，没有好处。","anal":"未济是尚未成功。事未成，有无限可能；但快要成功之时，最容易功败垂成。《周易》以未济收尾，寓意变化无穷，永无终点。"},"lines":[{"label":"初六","text":"濡其尾，吝","trans":"沾湿尾巴，有遗憾。","anal":"渡河刚开始，力量不足，急于前进受挫。"},{"label":"九二","text":"曳其轮，贞吉","trans":"拉住车轮，守正吉祥。","anal":"懂得节制，稳住节奏，不冒进。"},{"label":"六三","text":"未济，征凶，利涉大川","trans":"尚未成功，贸然进取凶险；但在合适时机，可以渡过大河。","anal":"时机未到不可强攻，看准险难可以突破。"},{"label":"九四","text":"贞吉，悔亡。震用伐鬼方，三年有赏于大国","trans":"守正吉祥，悔恨消失。奋起征伐鬼方，三年成功，得到大国封赏。","anal":"长久坚持，奋力建功，终获成功。"},{"label":"六五","text":"贞吉，无悔。君子之光，有孚，吉","trans":"守正吉祥，没有悔恨。君子的光辉，心怀诚信，吉祥。","anal":"以德发光，以诚感召，光明正大。"},{"label":"上九","text":"有孚于饮酒，无咎。濡其首，有孚失是","trans":"诚信安乐，饮酒自乐，无过错；如果沉溺享乐，沾湿头部，虽有诚信，也失正道。","anal":"事成之后可以安乐，但不可沉溺放纵。"}],"yong":null}],"basics":{"yinYang":[{"key":"阳爻","glyph":"—","title":"阳爻","desc":"一条连续长横线，记作「九」。象征：刚健、主动、光明、进取、天、力量、君子、奇数。"},{"key":"阴爻","glyph":"- -","title":"阴爻","desc":"断开两短横线，记作「六」。象征：柔顺、包容、沉静、退让、地、承载、收敛、偶数。"}],"yinYangNote":"阴阳不是好坏，是两种相反又互补的力量，万物都有阴阳两面。","origin":"太极生两仪（阴阳），两仪生四象，四象生八卦。八卦又叫经卦，每卦由 3 个爻组成；把两个八卦上下叠在一起（上卦 + 下卦），六爻成卦，就是六十四卦，又叫重卦。画卦顺序：从下往上画，最下面是初爻，往上依次：初、二、三、四、五、上。","mnemonic":"乾三连，坤六断；震仰盂，艮覆碗；离中虚，坎中满；兑上缺，巽下断。","trigramTable":[{"name":"乾","pinyin":"qián","sym":"☰","image":"天","virtue":"健，自强不息"},{"name":"坤","pinyin":"kūn","sym":"☷","image":"地","virtue":"顺，厚德载物"},{"name":"震","pinyin":"zhèn","sym":"☳","image":"雷","virtue":"动，警醒奋起"},{"name":"艮","pinyin":"gèn","sym":"☶","image":"山","virtue":"止，知止克制"},{"name":"离","pinyin":"lí","sym":"☲","image":"火","virtue":"明，依附、光明"},{"name":"坎","pinyin":"kǎn","sym":"☵","image":"水","virtue":"险，险中守正"},{"name":"兑","pinyin":"duì","sym":"☱","image":"泽","virtue":"悦，和乐沟通"},{"name":"巽","pinyin":"xùn","sym":"☴","image":"风","virtue":"入，顺势谦逊"}],"coinMethod":{"title":"金钱卦（纳甲摇卦）","prep":"准备 3 枚一样的铜钱（或 3 枚一元硬币）。约定：正面 = 阳（○），反面 = 阴（●），固定不变。","steps":["一共摇 6 次，从下往上记录，顺序是初爻 → 上爻，千万不要反。","3 个正面：老阳（○，动爻，阳变阴）。","2 正 1 反：少阳（—，不动）。","1 正 2 反：少阴（- -，不动）。","3 个反面：老阴（×，动爻，阴变阳）。"],"note":"老阳、老阴就是动爻，代表事情会变化；不动的少阳少阴，是本卦本体。摇完 6 次，先排出本卦；把所有老阳老阴反向一变，得到变卦。","example":"举例：自下而上摇出 少阳、少阴、老阳、少阳、少阴、老阴 → 先写本卦；再把老阳变阴、老阴变阳，得到变卦。解卦优先看动爻的爻辞。"}}};
